import pty, os, select, time, struct, fcntl, termios, sys
def interact(inputs, cols=80, rows=24, env_extra=None, cwd=None, args=None):
    pid, fd = pty.fork()
    if pid == 0:
        env=dict(os.environ); env["HOME"]="/tmp/fh4"; env["TERM"]="xterm-256color"
        if env_extra:
            for k,v in env_extra.items():
                if v is None: env.pop(k,None)
                else: env[k]=v
        if cwd: os.chdir(cwd)
        a=["/workspace/executable"]+(args if args is not None else ["--norc"])
        os.execve("/workspace/executable", a, env)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0,0))
    out=b""
    def drain(timeout=0.5):
        nonlocal out
        end=time.time()+timeout
        while time.time()<end:
            r,_,_=select.select([fd],[],[],0.05)
            if r:
                try: data=os.read(fd,65536)
                except OSError: break
                if not data: break
                out+=data; end=time.time()+0.25
    drain(1.0)
    for inp in inputs:
        if isinstance(inp,(int,float)): time.sleep(inp); drain(0.5); continue
        os.write(fd, inp); drain(0.7)
    status=None
    try:
        _, status, _ = os.waitpid(pid, os.WNOHANG)
    except: pass
    try: os.close(fd)
    except: pass
    try: os.kill(pid,9)
    except: pass
    try: os.waitpid(pid,0)
    except: pass
    return out

def show(label, inputs, **kw):
    out=interact(inputs, **kw)
    print(f"=== {label} ===")
    # strip to readable by replacing esc
    txt=out.decode(errors="replace")
    print(txt.replace("\x1b","<ESC>")[-3000:])
    print("---repr tail---")
    print(repr(out[-2000:]))

