#!/usr/bin/env python3
import os, sys, re, signal, time, errno, stat

VERSION = "0.4.2"

def ewrite(fd, s):
    if isinstance(s, str):
        s = s.encode('utf-8', 'surrogateescape')
    try:
        while s:
            n = os.write(fd, s)
            s = s[n:]
    except OSError:
        pass

def rust_os_error(e):
    # Format like Rust std::io::Error debug: Os { code: 2, kind: NotFound, message: "No such file or directory" }
    kinds = {
        errno.ENOENT: "NotFound", errno.EACCES: "PermissionDenied", errno.EISDIR: "IsADirectory",
        errno.ENOTDIR: "NotADirectory", errno.EEXIST: "AlreadyExists", errno.EPERM: "PermissionDenied",
        errno.EINVAL: "InvalidInput", errno.EPIPE: "BrokenPipe", errno.ENOTEMPTY: "DirectoryNotEmpty",
    }
    kind = kinds.get(e.errno, "Other")
    msg = os.strerror(e.errno) if e.errno else str(e)
    return f'Os {{ code: {e.errno}, kind: {kind}, message: "{msg}" }}'

class ParseError(Exception):
    def __init__(self, pos, expected, source=None):
        self.pos = pos
        self.expected = expected
    def render(self, source):
        pos = self.pos
        # compute line/col (1-based)
        before = source[:pos]
        line_no = before.count('\n') + 1
        last_nl = before.rfind('\n')
