SIMPLE_EXPECTED = "word, escaped_char, unescaped_char, literal_span, any_string_span, any_char_span, command_span, proc_subst_direction, backtick_span, expr_span, param_ex_span, param_span, double_quoted_span, single_quoted_span, redirect_direction, heredoc, and_or_list_sep, or compound_list_sep"

# ---------------- Arithmetic ----------------
class ArithParser:
    def __init__(self, text, pos=0):
        self.s = text; self.pos = pos; self.n = len(text)
