            if p < self.n and self.s[p] == '=' and not (p+1 < self.n and self.s[p+1] == '='):
                self.pos = p + 1
                rhs = self.parse_assign()
                return Node('a_assign', name=m.group(0), rhs=rhs)
            self.pos = save
