            num = None
            if self.pos < self.n and self.s[self.pos] not in ';\n&|':
                m = re.match(r'-?[0-9]+', self.s[self.pos:])
                if m:
                    num = m.group(0); self.pos += m.end()
                else:
                    self.err(self.pos, "EOI, num, and_or_list_sep, or compound_list_sep")
            return Node('return', num=num, start=start)
        if w in ('break','continue'):
            self.pos += len(w)
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] not in ';\n&|)#}':
                # check stop words like fi/done could follow after ; only; any arg is error
                if self.peek_char() != '':
                    self.err(self.pos, "EOI, and_or_list_sep, or compound_list_sep")
            return Node(w, start=start)
        # function definition lookahead: name () body
        m = re.match(r'([A-Za-z0-9_]+)[ \t]*\(\)', self.s[self.pos:])
        if m:
            name = m.group(1)
            self.pos += m.end()
            self.skip_spaces_newlines()
            body = self.parse_command()
            return Node('funcdef', name=name, body=body, start=start)
        return self.parse_simple()

    def parse_local(self):
        start = self.pos
        self.pos += len('local')
        entries = []
        # must have at least one var_name
        while True:
            self.skip_spaces()
            if self.pos >= self.n or self.s[self.pos] in ';\n&|)':
                break
            if self.s[self.pos] == '#':
                break
            m = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
            if not m:
                self.err(self.pos, "var_name")
            name = m.group(0); self.pos += m.end()
            # optional [idx]
            idx = None
            if self.pos < self.n and self.s[self.pos] == '[':
                close = self.s.find(']', self.pos)
                if close == -1:
                    self.err(self.pos, "assign")
                idx = self.s[self.pos+1:close]; self.pos = close + 1
            if self.pos < self.n and self.s[self.pos] == '=':
                self.pos += 1
                if self.pos < self.n and self.s[self.pos] == '(':
                    val = self.parse_array_initializer()
                    entries.append(Node('assign', name=name, index=idx, array=val))
                else:
                    if self.pos >= self.n or self.s[self.pos] in ' \t;\n&|':
                        self.err(self.pos, WORD_EXPECTED + ", or initializer")
                    val = self.parse_word()
                    entries.append(Node('assign', name=name, index=idx, value=val))
            else:
                entries.append(Node('assign', name=name, index=idx, value=None))
        if not entries:
            self.err(self.pos, "var_name")
        return Node('local', entries=entries, start=start)

    def parse_array_initializer(self):
        # pos at '('
        self.pos += 1
        elements = []
        while True:
            self.skip_spaces_newlines()
            if self.pos < self.n and self.s[self.pos] == ')':
                self.pos += 1; break
            if self.pos >= self.n:
                self.err(self.pos, "word or normal_newline")
            w = self.parse_word()
            elements.append(w)
        return elements

    def try_assignment(self):
        # at pos, see if NAME([..])? = ; if so parse and return assign Node else None (restore)
        save = self.pos
        m = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
        if not m:
            return None
        name = m.group(0); p = self.pos + m.end()
        idx = None
        if p < self.n and self.s[p] == '[':
            close = self.s.find(']', p)
            if close == -1:
                return None
            idx = self.s[p+1:close]; p = close + 1
        if p < self.n and self.s[p] == '=':
            self.pos = p + 1
            if self.pos < self.n and self.s[self.pos] == '(':
                arr = self.parse_array_initializer()
                return Node('assign', name=name, index=idx, array=arr)
            if self.pos >= self.n or self.s[self.pos] in ' \t;\n&|)<':
                self.err(self.pos, WORD_EXPECTED + ", or initializer")
            val = self.parse_word()
            return Node('assign', name=name, index=idx, value=val)
        self.pos = save
        return None

    def parse_simple(self):
        start = self.pos
        assigns = []
        words = []
        redirects = []
        got_word = False
        while True:
            self.skip_spaces()
            if self.pos >= self.n:
                break
            c = self.s[self.pos]
            if c in ';\n&|)':
                break
            if c == '#':
                break
            if c == '(':
                self.err(self.pos, "EOI, " + SIMPLE_EXPECTED)
            if c in '{}':
                self.err(self.pos, "EOI, word, redirect_direction, heredoc, and_or_list_sep, or compound_list_sep")
            # redirect?
            redir = self.try_parse_redirect()
            if redir is not None:
                redirects.append(redir); continue
            if not got_word:
                assign = self.try_assignment()
                if assign is not None:
                    assigns.append(assign); continue
            # word
            if c == '(':
                self.err(self.pos, "EOI, " + SIMPLE_EXPECTED)
            w = self.parse_word()
            words.append(w); got_word = True
        return Node('simple', assigns=assigns, words=words, redirects=redirects, start=start, end=self.pos)

    def try_parse_redirect(self):
        save = self.pos
        fd = None
        m = re.match(r'[0-9]+', self.s[self.pos:])
        if m and self.pos + m.end() < self.n and self.s[self.pos+m.end()] in '<>':
            fd = int(m.group(0)); self.pos += m.end()
        elif self.s[self.pos] in '<>':
            pass
        else:
            return None
        # now at < or >
        if self.pos >= self.n or self.s[self.pos] not in '<>':
            self.pos = save; return None
        direction = self.s[self.pos]
        # operators
        if direction == '>':
            if self.starts('>>'):
                op = '>>'; self.pos += 2
            elif self.starts('>&'):
                op = '>&'; self.pos += 2
            elif self.starts('>'):
                op = '>'; self.pos += 1
            else:
                op = '>'; self.pos += 1
        else: # '<'
            if self.starts('<<'):
                op = '<<'; self.pos += 2
            elif self.starts('<&'):
                op = '<&'; self.pos += 2
            elif self.starts('<'):
                op = '<'; self.pos += 1
            else:
                op = '<'; self.pos += 1
        if op in ('>&','<&'):
            self.skip_spaces()
            # target may be '-' or digits or word
            if self.pos < self.n and (self.s[self.pos].isdigit()):
                m2 = re.match(r'[0-9]+', self.s[self.pos:])
                target = m2.group(0); self.pos += m2.end()
                return Node('redirect', fd=fd, op=op, target_fd=int(target))
            elif self.pos < self.n and self.s[self.pos] == '-':
                # original panics parsing empty fd? >&- gives ParseIntError Empty panic; emulate via marker
                self.pos += 1
                return Node('redirect', fd=fd, op=op, target_fd='-')
            else:
                # parse a word as target, its expansion will be used for panic handling
                if self.pos >= self.n or self.s[self.pos] in ';\n&|':
                    raise ShellPanic("src/parser.rs:868:22", "called `Result::unwrap()` on an `Err` value: ParseIntError { kind: Empty }")
                tw = self.parse_word()
                return Node('redirect', fd=fd, op=op, target_word=tw)
        if op == '<<':
            self.skip_spaces()
            # heredoc marker: raw word characters [A-Za-z0-9_.\-]+ (?) must not start with quote
            if self.pos >= self.n or not (self.s[self.pos].isalnum() or self.s[self.pos] in '_'):
                self.err(self.pos, "heredoc_marker")
            m2 = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
            marker = m2.group(0); self.pos += m2.end()
            node = Node('redirect', fd=fd, op=op, heredoc_marker=marker, heredoc_lines=[])
            self.pending_heredocs.append(node)
            if len([r for r in self.pending_heredocs]) > 1:
                # multiple heredocs on same line: original panics at execution/parsing stage; flag it
                node.multi = True
            return node
        # file redirect
        self.skip_spaces()
        if self.pos >= self.n or self.s[self.pos] in ';\n&|':
            self.err(self.pos, "word or redirect_to_fd")
        target = self.parse_word()
        return Node('redirect', fd=fd, op=op, target=target)

    # ----- compound -----
    def parse_if(self):
        start = self.pos
        self.pos += 2
        cond = self.parse_list(stop_reserved={'then'}, stop_chars=set())
        self.skip_spaces()
        if self.peek_reserved() != 'then':
            self.err(self.pos, "elif_part, else_part, and_or_list_sep, or compound_list_sep")
        self.pos += 4
        then_body = self.parse_list(stop_reserved={'elif','else','fi'}, stop_chars=set())
        elifs = []
        else_body = None
        while True:
            self.skip_spaces()
            # newlines already consumed in parse_list
            w = self.peek_reserved()
            if w == 'elif':
                self.pos += 4
                ec = self.parse_list(stop_reserved={'then'}, stop_chars=set())
                if self.peek_reserved() != 'then':
                    self.err(self.pos, "word")
                self.pos += 4
                eb = self.parse_list(stop_reserved={'elif','else','fi'}, stop_chars=set())
                elifs.append((ec, eb))
            elif w == 'else':
                self.pos += 4
                else_body = self.parse_list(stop_reserved={'fi'}, stop_chars=set())
                break
            else:
                break
        self.skip_spaces()
        if self.peek_reserved() != 'fi':
            self.err(self.pos, "word, escaped_char, unescaped_char, " + WORD_EXPECTED + ", redirect_direction, heredoc, elif_part, else_part, and_or_list_sep, or compound_list_sep")
        self.pos += 2
        return Node('if', cond=cond, then_body=then_body, elifs=elifs, else_body=else_body, start=start)

    def parse_while(self):
        start = self.pos
        self.pos += 5
        cond = self.parse_list(stop_reserved={'do'}, stop_chars=set())
        if self.peek_reserved() != 'do':
            self.err(self.pos, "EOI, normal_newline, command, or compound_list_sep")
        self.pos += 2
        body = self.parse_list(stop_reserved={'done'}, stop_chars=set())
        if self.peek_reserved() != 'done':
            self.err(self.pos, "EOI, and_or_list_sep, or compound_list_sep")
        self.pos += 4
        return Node('while', cond=cond, body=body, start=start)

    def parse_for(self):
        start = self.pos
        self.pos += 3
        self.skip_spaces()
        if self.starts('(('):
            # arith for
            self.pos += 2
            ap = ArithParser(self.s, self.pos)
            try:
                init = ap.parse()
            except Exception:
                self.err(self.pos, "assign")
            self.pos = ap.pos; self.skip_spaces()
            if self.peek_char() != ';':
                self.err(self.pos, "comp_op, assign_op, arith_op, or factor_op")
            self.pos += 1
            ap = ArithParser(self.s, self.pos)
            try: cond = ap.parse()
            except Exception: self.err(self.pos, "assign")
            self.pos = ap.pos; self.skip_spaces()
            if self.peek_char() != ';': self.err(self.pos, "assign")
            self.pos += 1
            ap = ArithParser(self.s, self.pos)
            try: incr = ap.parse()
            except Exception: self.err(self.pos, "assign")
            self.pos = ap.pos; self.skip_spaces()
            if not self.starts('))'):
                self.err(self.pos, "assign")
            self.pos += 2
            # expect ; or newline then do
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] == ';': self.pos += 1
            while self.pos < self.n and self.s[self.pos] == '\n':
                self.pos += 1; self.process_heredocs()
            self.skip_spaces()
            if self.peek_reserved() != 'do':
                self.err(self.pos, "normal_newline")
            self.pos += 2
            body = self.parse_list(stop_reserved={'done'}, stop_chars=set())
            if self.peek_reserved() != 'done': self.err(self.pos, "EOI, and_or_list_sep, or compound_list_sep")
            self.pos += 4
            return Node('arithfor', init=init, cond=cond, incr=incr, body=body, start=start)
        m = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
        if not m:
            self.err(self.pos, "arith_for_exprs")
        var = m.group(0); self.pos += m.end()
        self.skip_spaces()
        words = []
        if self.peek_reserved() == 'in':
            self.pos += 2
            while True:
                self.skip_spaces()
                if self.pos >= self.n or self.s[self.pos] in ';\n':
                    break
                if self.peek_reserved() == 'do':
                    break
                words.append(self.parse_word())
        else:
            self.err(self.pos, "arith_for_exprs")
        # separator
        if self.pos < self.n and self.s[self.pos] == ';': self.pos += 1
        while self.pos < self.n and self.s[self.pos] == '\n':
            self.pos += 1; self.process_heredocs()
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] == ';': self.pos += 1
        self.skip_spaces()
        if self.peek_reserved() != 'do':
            self.err(self.pos, "word or normal_newline")
        self.pos += 2
        body = self.parse_list(stop_reserved={'done'}, stop_chars=set())
        if self.peek_reserved() != 'done':
            self.err(self.pos, "EOI, and_or_list_sep, or compound_list_sep")
        self.pos += 4
        return Node('for', var=var, words=words, body=body, start=start)

    def parse_case(self):
        start = self.pos
        self.pos += 4
        self.skip_spaces()
        subject = self.parse_word()
        self.skip_spaces()
        if self.peek_reserved() != 'in':
            self.err(self.pos, "word or normal_newline")
        self.pos += 2
        items = []
        while True:
            while self.pos < self.n and self.s[self.pos] in ' \t\n':
                if self.s[self.pos] == '\n': self.pos += 1; self.process_heredocs()
                else: self.pos += 1
            if self.pos >= self.n:
                self.err(self.pos, "word or normal_newline")
            if self.peek_reserved() == 'esac':
                self.pos += 4; break
            # patterns
            patterns = []
            while True:
                self.skip_spaces()
                pat = self.parse_word(in_case_pattern=True)
                patterns.append(pat)
                self.skip_spaces()
                if self.pos < self.n and self.s[self.pos] == '|':
                    self.pos += 1; continue
                break
            self.skip_spaces()
            if self.pos >= self.n or self.s[self.pos] != ')':
                self.err(self.pos, "word or normal_newline")
            self.pos += 1
            body = self.parse_list(stop_reserved={'esac'}, stop_chars=set(), stop_ddsemi=True)
            if self.starts(';;'):
                self.pos += 2
            items.append(Node('caseitem', patterns=patterns, body=body))
            # loop
        return Node('case', subject=subject, items=items, start=start)

    def parse_conditional(self):
        start = self.pos
        self.pos += 2
        expr = self.parse_cond_or()
        self.skip_spaces()
        if not self.starts(']]'):
            self.err(self.pos, "escaped_char, unescaped_char, literal_span, any_string_span, any_char_span, command_span, proc_subst_direction, backtick_span, expr_span, param_ex_span, param_span, double_quoted_span, single_quoted_span, or cond_op")
        self.pos += 2
        return Node('conditional', expr=expr, start=start)
    def parse_cond_or(self):
        left = self.parse_cond_and()
        while True:
            self.skip_spaces()
            if self.starts('||'):
                self.pos += 2; right = self.parse_cond_and(); left = Node('cond_bin', op='||', left=left, right=right)
            else: break
        return left
    def parse_cond_and(self):
        left = self.parse_cond_primary()
        while True:
            self.skip_spaces()
            if self.starts('&&'):
                self.pos += 2; right = self.parse_cond_primary(); left = Node('cond_bin', op='&&', left=left, right=right)
            else: break
        return left
    def parse_cond_primary(self):
        self.skip_spaces()
        if self.pos < self.n and self.s[self.pos] == '(':
            raise ShellPanic("src/parser.rs:661:18", "internal error: entered unreachable code")
        left = self.parse_word(in_conditional=True)
        self.skip_spaces()
        # check operator
        op = None
        for cand in ('==','!=','-eq','-ne','-lt','-le','-gt','-ge','='):
            if self.s.startswith(cand, self.pos):
                # ensure boundary for -xx and = etc
                after = self.pos+len(cand)
                if cand.startswith('-'):
                    if after < self.n and (self.s[after].isalnum() or self.s[after]=='_'):
                        continue
                op = cand; break
        if op:
            self.pos += len(op)
            self.skip_spaces()
            right = self.parse_word(in_conditional=True)
            return Node('cond_cmp', op=op, left=left, right=right)
        # if next token is not ]] / && / ||, error expected cond_op
        if not (self.starts(']]') or self.starts('&&') or self.starts('||')):
            if self.pos < self.n:
                self.err(self.pos, "cond_op")
        return Node('cond_single', word=left)

    # ---------- words ----------
    def parse_word(self, in_heredoc=False, in_case_pattern=False, in_conditional=False):
        start = self.pos
        spans = []
        first = True
        while self.pos < self.n:
            c = self.s[self.pos]
            if c in ' \t\n':
                break
            if in_case_pattern and c in '|)':
                break
            if in_conditional and (self.starts(']]') and False):
                break
            if c in ';&|':
                # | is pattern sep handled above; & | are delimiters generally
                break
            if c in '<>' and not in_heredoc:
                break
            if c in '()':
                break
            if c in '{}':
                break
            if c == '#':
                # literal if not at ... comments only handled at list level when separated; inside word it's literal
                # append as literal
                spans.append(('lit', '#')); self.pos += 1; first = False; continue
            if c == '\\':
                if self.pos + 1 < self.n:
                    nxt = self.s[self.pos+1]
                    spans.append(('lit', nxt)); self.pos += 2; first = False; continue
                else:
                    spans.append(('lit', '\\')); self.pos += 1; continue
            if c == '\'':
                # single quoted
                self.pos += 1
                endq = self.s.find('\'', self.pos)
                if endq == -1:
                    self.err(self.n, "literal_in_single_quoted_span")
                content = self.s[self.pos:endq]
                spans.append(('squote', content)); self.pos = endq + 1; first = False; continue
            if c == '"':
                dq = self.parse_dquote()
                spans.append(dq); first = False; continue
            if c == '`':
                bt = self.parse_backtick()
                spans.append(bt); first = False; continue
            if c == '$':
                span = self.parse_dollar(in_heredoc=in_heredoc)
                spans.append(span); first = False; continue
            if c == '~' and first:
                # tilde span
                self.pos += 1
                m = re.match(r'[^/ \t\n;|&<>(){}\'"$`\\]*', self.s[self.pos:])
                user = m.group(0) if m else ''
                self.pos += len(user)
                spans.append(('tilde', user)); first = False; continue
            if c == '*':
                spans.append(('star',)); self.pos += 1; first = False; continue
            if c == '?':
                spans.append(('qmark',)); self.pos += 1; first = False; continue
            if c in '<>' and False:
                break
            if (c == '<' or c == '>') and self.pos+1 < self.n and self.s[self.pos+1] == '(':
                # proc subst - handled in parse_dollar? no, it's here
                # Actually < > are break above, so unreachable
                pass
            # literal run
            lit_start = self.pos
            while self.pos < self.n:
                ch = self.s[self.pos]
                if ch in ' \t\n;&|<>(){}\'"$`\\*?':
                    break
                if ch == '#' :
                    # include
                    pass
                self.pos += 1
            if self.pos == lit_start:
                # unknown char, consume one as literal to avoid loop
                spans.append(('lit', c)); self.pos += 1
            else:
                spans.append(('lit', self.s[lit_start:self.pos]))
            first = False
        return Word(spans, start, self.pos)

