# ---------------- Parser ----------------
class Parser:
    def __init__(self, text):
        self.s = text
        self.n = len(text)
        self.pos = 0
        self.pending_heredocs = []

    def err(self, pos, expected):
        raise ParseError(pos, expected)

    def parse(self):
        lst = self.parse_list(stop_reserved=set(), stop_chars=set())
        self.skip_spaces()
        # process heredocs if ending with newline-less? pending would remain if EOF without newline; if body present it would have been handled at newline
        if self.pos < self.n:
            self.err(self.pos, "EOI, command, or compound_list_sep")
        return lst

    # utilities
    def skip_spaces(self):
        while self.pos < self.n and self.s[self.pos] in ' \t':
            self.pos += 1
    def skip_spaces_newlines(self):
        while self.pos < self.n and self.s[self.pos] in ' \t\n':
            self.pos += 1
    def peek_char(self):
        return self.s[self.pos] if self.pos < self.n else ''
    def starts(self, txt):
        return self.s.startswith(txt, self.pos)
    def peek_reserved(self):
        # returns reserved word at current pos if bounded
        m = re.match(r'[A-Za-z_][A-Za-z0-9_]*', self.s[self.pos:])
        if not m:
            return None
        w = m.group(0)
        after = self.pos + m.end()
        if after < self.n and (self.s[after].isalnum() or self.s[after] == '_'):
            return None
        return w
    def at_stop(self, stop_reserved, stop_chars):
        if self.pos >= self.n:
            return True
        c = self.s[self.pos]
        if c in stop_chars:
            return True
        w = self.peek_reserved()
        if w and w in stop_reserved:
            return True
        return False

    def process_heredocs(self):
        # Called after consuming a newline that terminates a statement line
        while self.pending_heredocs:
            redir = self.pending_heredocs.pop(0)
            marker = redir.heredoc_marker
            lines = []
            while True:
                if self.pos >= self.n:
                    self.err(self.pos, "word, escaped_char, unescaped_char, literal_span, any_string_span, any_char_span, command_span, proc_subst_direction, backtick_span, expr_span, param_ex_span, param_span, double_quoted_span, or single_quoted_span")
                nl = self.s.find('\n', self.pos)
                if nl == -1:
                    line = self.s[self.pos:]
                    line_end = self.n
                    next_pos = self.n
                else:
                    line = self.s[self.pos:nl]
                    line_end = nl
                    next_pos = nl + 1
                if line == marker:
                    self.pos = next_pos
                    break
                # parse words in this line
                words = []
                # parse using a bounded approach: temporarily limit? parse_word stops at newline via delimiter
                save_line_bound = line_end
                # parse words until line_end
                while True:
                    while self.pos < save_line_bound and self.s[self.pos] in ' \t':
                        self.pos += 1
                    if self.pos >= save_line_bound:
                        break
                    w = self.parse_word(in_heredoc=True)
                    words.append(w)
                # move to next line
                self.pos = next_pos
                lines.append(words)
            redir.heredoc_lines = lines

    def parse_list(self, stop_reserved, stop_chars, stop_ddsemi=False):
        items = []
        while True:
            # skip separators/blank lines
            while True:
                self.skip_spaces()
                if self.pos < self.n and self.s[self.pos] == '#':
                    # comment to end of line
                    nl = self.s.find('\n', self.pos)
                    self.pos = self.n if nl == -1 else nl
                    continue
                if self.pos < self.n and self.s[self.pos] == '\n':
                    self.pos += 1
                    self.process_heredocs()
                    continue
                if self.pos < self.n and self.s[self.pos] == ';':
                    # a leading ; when expecting a command: if next is also ; it's error handled by andor parse, but single stray ; is allowed as empty
                    # consume and continue only if we haven't just... we track: allow if items empty or previous separator already consumed? simpler: consume lone ;
                    # But ';;' should error: if two in a row with nothing between
                    nxt = self.pos + 1
                    # look ahead skipping spaces
                    p = nxt
                    while p < self.n and self.s[p] in ' \t': p += 1
                    if p < self.n and self.s[p] == ';' and not stop_ddsemi:
                        self.err(self.pos, "EOI, word, escaped_char, unescaped_char, " + WORD_EXPECTED + ", redirect_direction, heredoc, and_or_list_sep, or compound_list_sep")
                    self.pos += 1
                    continue
                break
            if self.pos >= self.n:
                break
            if stop_ddsemi and self.starts(';;'):
                break
            if self.at_stop(stop_reserved, stop_chars):
                break
            if self.s[self.pos] in stop_chars:
                break
            andor = self.parse_andor()
            # terminator
            bg = False
            # Determine separator that follows is handled by outer loop; but need know if '&' directly terminates this andor
            # Peek: skip spaces
            save = self.pos
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] == '&' and not self.starts('&&'):
                bg = True
                self.pos += 1
                # after & it's a separator; loop will continue
            elif self.pos < self.n and self.s[self.pos] == ';':
                # check for ;; case handled at top
                pass
            else:
                self.pos = save if False else self.pos
            items.append(Node('item', andor=andor, background=bg))
            # if next is not a separator/stop/eof, error
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] not in ';\n&' and not self.at_stop(stop_reserved, stop_chars) and self.s[self.pos] not in stop_chars:
                # Could be ')' etc handled by stop; else error
                if stop_ddsemi and self.starts(';;'):
                    pass
                else:
                    self.err(self.pos, "EOI, and_or_list_sep, or compound_list_sep")
            # loop continues; separator consumption at top
        return Node('list', items=items)

    def parse_andor(self):
        start = self.pos
        first = self.parse_pipeline()
        rest = []
        while True:
            save = self.pos
            self.skip_spaces()
            if self.starts('&&'):
                op = '&&'; self.pos += 2
            elif self.starts('||'):
                op = '||'; self.pos += 2
            else:
                self.pos = save; break
            # allow newline after operator (does not trigger heredoc)
            while self.pos < self.n and self.s[self.pos] in ' \t\n':
                if self.s[self.pos] == '\n':
                    self.pos += 1
                else:
                    self.pos += 1
            nxt = self.parse_pipeline()
            rest.append((op, nxt))
        end = self.pos
        return Node('andor', first=first, rest=rest, start=start, end=end)

    def parse_pipeline(self):
        cmds = [self.parse_command()]
        while True:
            save = self.pos
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] == '|' and not self.starts('||'):
                self.pos += 1
                while self.pos < self.n and self.s[self.pos] in ' \t\n':
                    self.pos += 1
                cmds.append(self.parse_command())
            else:
                self.pos = save; break
        return Node('pipeline', commands=cmds)

    # ---------- commands ----------
    def parse_command(self):
        self.skip_spaces()
        start = self.pos
        if self.pos >= self.n:
            self.err(self.pos, "command")
        c = self.s[self.pos]
        if c == '(':
            self.pos += 1
            body = self.parse_list(stop_reserved=set(), stop_chars={')'})
            self.skip_spaces()
            # allow newlines before )
            while self.pos < self.n and self.s[self.pos] == '\n':
                self.pos += 1
                self.process_heredocs()
                body2 = self.parse_list(stop_reserved=set(), stop_chars={')'})
                body.items.extend(body2.items)
                self.skip_spaces()
            if self.pos >= self.n or self.s[self.pos] != ')':
                self.err(self.pos, "command or compound_list_sep")
            self.pos += 1
            return Node('subshell', body=body, start=start)
        if c == '{':
            # brace group: { list }
            # Need to ensure it's not ${ etc: at command start '{' alone
            self.pos += 1
            body = self.parse_list(stop_reserved=set(), stop_chars={'}'})
            while self.pos < self.n and self.s[self.pos] == '\n':
                self.pos += 1; self.process_heredocs()
                b2 = self.parse_list(stop_reserved=set(), stop_chars={'}'})
                body.items.extend(b2.items)
            self.skip_spaces()
            if self.pos >= self.n or self.s[self.pos] != '}':
                self.err(self.pos, "EOI, command, or compound_list_sep")
            self.pos += 1
            return Node('bracegroup', body=body, start=start)
        if self.starts('[[') and self.pos+2 < self.n and self.s[self.pos+2] in ' \t':
            return self.parse_conditional()
        w = self.peek_reserved()
        if w == 'if':
            return self.parse_if()
        if w == 'while':
            return self.parse_while()
        if w == 'for':
            return self.parse_for()
        if w == 'case':
            return self.parse_case()
        if w == 'function':
            # function name ...
            save = self.pos
            self.pos += len('function')
            self.skip_spaces()
            m = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
            if not m:
                self.err(save, "EOI, command, or compound_list_sep")
            name = m.group(0); self.pos += m.end()
            self.skip_spaces()
            if self.starts('()'):
                self.pos += 2
            self.skip_spaces_newlines()
            body = self.parse_command()
            return Node('funcdef', name=name, body=body, start=start)
        if w in ('then','else','elif','fi','do','done','esac','in'):
            self.err(self.pos, "EOI, command, or compound_list_sep")
        if w == 'local':
            return self.parse_local()
        if w == 'return':
            self.pos += len('return')
            self.skip_spaces()
            num = None
            if self.pos < self.n and self.s[self.pos] not in ';\n&|':
                m = re.match(r'-?[0-9]+', self.s[self.pos:])
                if m:
                    num = m.group(0); self.pos += m.end()
                else:
                    self.err(self.pos, "EOI, num, and_or_list_sep, or compound_list_sep")
            return Node('return', num=num, start=start)
        if w in ('break','continue'):
            self.pos += len(w)
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] not in ';\n&|)#}':
                # check stop words like fi/done could follow after ; only; any arg is error
                if self.peek_char() != '':
                    self.err(self.pos, "EOI, and_or_list_sep, or compound_list_sep")
            return Node(w, start=start)
        # function definition lookahead: name () body
        m = re.match(r'([A-Za-z0-9_]+)[ \t]*\(\)', self.s[self.pos:])
        if m:
            name = m.group(1)
            self.pos += m.end()
            self.skip_spaces_newlines()
            body = self.parse_command()
            return Node('funcdef', name=name, body=body, start=start)
        return self.parse_simple()

    def parse_local(self):
        start = self.pos
        self.pos += len('local')
        entries = []
        # must have at least one var_name
        while True:
            self.skip_spaces()
            if self.pos >= self.n or self.s[self.pos] in ';\n&|)':
                break
            if self.s[self.pos] == '#':
                break
            m = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
            if not m:
                self.err(self.pos, "var_name")
            name = m.group(0); self.pos += m.end()
            # optional [idx]
            idx = None
            if self.pos < self.n and self.s[self.pos] == '[':
                close = self.s.find(']', self.pos)
                if close == -1:
                    self.err(self.pos, "assign")
                idx = self.s[self.pos+1:close]; self.pos = close + 1
            if self.pos < self.n and self.s[self.pos] == '=':
                self.pos += 1
                if self.pos < self.n and self.s[self.pos] == '(':
                    val = self.parse_array_initializer()
                    entries.append(Node('assign', name=name, index=idx, array=val))
                else:
                    if self.pos >= self.n or self.s[self.pos] in ' \t;\n&|':
                        self.err(self.pos, WORD_EXPECTED + ", or initializer")
                    val = self.parse_word()
                    entries.append(Node('assign', name=name, index=idx, value=val))
            else:
                entries.append(Node('assign', name=name, index=idx, value=None))
        if not entries:
            self.err(self.pos, "var_name")
        return Node('local', entries=entries, start=start)

    def parse_array_initializer(self):
        # pos at '('
        self.pos += 1
        elements = []
        while True:
            self.skip_spaces_newlines()
            if self.pos < self.n and self.s[self.pos] == ')':
                self.pos += 1; break
            if self.pos >= self.n:
                self.err(self.pos, "word or normal_newline")
            w = self.parse_word()
            elements.append(w)
        return elements

    def try_assignment(self):
        # at pos, see if NAME([..])? = ; if so parse and return assign Node else None (restore)
        save = self.pos
        m = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
        if not m:
            return None
        name = m.group(0); p = self.pos + m.end()
        idx = None
        if p < self.n and self.s[p] == '[':
            close = self.s.find(']', p)
            if close == -1:
                return None
            idx = self.s[p+1:close]; p = close + 1
        if p < self.n and self.s[p] == '=':
            self.pos = p + 1
            if self.pos < self.n and self.s[self.pos] == '(':
                arr = self.parse_array_initializer()
                return Node('assign', name=name, index=idx, array=arr)
            if self.pos >= self.n or self.s[self.pos] in ' \t;\n&|)<':
                self.err(self.pos, WORD_EXPECTED + ", or initializer")
            val = self.parse_word()
            return Node('assign', name=name, index=idx, value=val)
        self.pos = save
        return None

    def parse_simple(self):
        start = self.pos
        assigns = []
        words = []
        redirects = []
        got_word = False
        while True:
            self.skip_spaces()
            if self.pos >= self.n:
                break
            c = self.s[self.pos]
            if c in ';\n&|)':
                break
            if c == '#':
                break
            if c == '(':
                self.err(self.pos, "EOI, " + SIMPLE_EXPECTED)
            if c in '{}':
                self.err(self.pos, "EOI, word, redirect_direction, heredoc, and_or_list_sep, or compound_list_sep")
            # redirect?
            redir = self.try_parse_redirect()
            if redir is not None:
                redirects.append(redir); continue
            if not got_word:
                assign = self.try_assignment()
                if assign is not None:
                    assigns.append(assign); continue
            # word
            if c == '(':
                self.err(self.pos, "EOI, " + SIMPLE_EXPECTED)
            w = self.parse_word()
            words.append(w); got_word = True
        return Node('simple', assigns=assigns, words=words, redirects=redirects, start=start, end=self.pos)

    def try_parse_redirect(self):
        save = self.pos
        fd = None
        m = re.match(r'[0-9]+', self.s[self.pos:])
        if m and self.pos + m.end() < self.n and self.s[self.pos+m.end()] in '<>':
            fd = int(m.group(0)); self.pos += m.end()
        elif self.s[self.pos] in '<>':
            pass
        else:
            return None
        # now at < or >
        if self.pos >= self.n or self.s[self.pos] not in '<>':
            self.pos = save; return None
        direction = self.s[self.pos]
        # operators
        if direction == '>':
            if self.starts('>>'):
                op = '>>'; self.pos += 2
            elif self.starts('>&'):
                op = '>&'; self.pos += 2
            elif self.starts('>'):
                op = '>'; self.pos += 1
            else:
                op = '>'; self.pos += 1
        else: # '<'
            if self.starts('<<'):
                op = '<<'; self.pos += 2
            elif self.starts('<&'):
                op = '<&'; self.pos += 2
            elif self.starts('<'):
                op = '<'; self.pos += 1
            else:
                op = '<'; self.pos += 1
        if op in ('>&','<&'):
            self.skip_spaces()
            # target may be '-' or digits or word
            if self.pos < self.n and (self.s[self.pos].isdigit()):
                m2 = re.match(r'[0-9]+', self.s[self.pos:])
                target = m2.group(0); self.pos += m2.end()
                return Node('redirect', fd=fd, op=op, target_fd=int(target))
            elif self.pos < self.n and self.s[self.pos] == '-':
                # original panics parsing empty fd? >&- gives ParseIntError Empty panic; emulate via marker
                self.pos += 1
                return Node('redirect', fd=fd, op=op, target_fd='-')
            else:
                # parse a word as target, its expansion will be used for panic handling
                if self.pos >= self.n or self.s[self.pos] in ';\n&|':
                    raise ShellPanic("src/parser.rs:868:22", "called `Result::unwrap()` on an `Err` value: ParseIntError { kind: Empty }")
                tw = self.parse_word()
                return Node('redirect', fd=fd, op=op, target_word=tw)
        if op == '<<':
            self.skip_spaces()
            # heredoc marker: raw word characters [A-Za-z0-9_.\-]+ (?) must not start with quote
            if self.pos >= self.n or not (self.s[self.pos].isalnum() or self.s[self.pos] in '_'):
                self.err(self.pos, "heredoc_marker")
            m2 = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
            marker = m2.group(0); self.pos += m2.end()
            node = Node('redirect', fd=fd, op=op, heredoc_marker=marker, heredoc_lines=[])
            self.pending_heredocs.append(node)
            if len([r for r in self.pending_heredocs]) > 1:
                # multiple heredocs on same line: original panics at execution/parsing stage; flag it
                node.multi = True
            return node
        # file redirect
        self.skip_spaces()
        if self.pos >= self.n or self.s[self.pos] in ';\n&|':
            self.err(self.pos, "word or redirect_to_fd")
        target = self.parse_word()
        return Node('redirect', fd=fd, op=op, target=target)

    # ----- compound -----
    def parse_if(self):
        start = self.pos
        self.pos += 2
        cond = self.parse_list(stop_reserved={'then'}, stop_chars=set())
        self.skip_spaces()
        if self.peek_reserved() != 'then':
            self.err(self.pos, "elif_part, else_part, and_or_list_sep, or compound_list_sep")
        self.pos += 4
        then_body = self.parse_list(stop_reserved={'elif','else','fi'}, stop_chars=set())
        elifs = []
        else_body = None
        while True:
            self.skip_spaces()
            # newlines already consumed in parse_list
            w = self.peek_reserved()
            if w == 'elif':
                self.pos += 4
                ec = self.parse_list(stop_reserved={'then'}, stop_chars=set())
                if self.peek_reserved() != 'then':
                    self.err(self.pos, "word")
                self.pos += 4
                eb = self.parse_list(stop_reserved={'elif','else','fi'}, stop_chars=set())
                elifs.append((ec, eb))
            elif w == 'else':
                self.pos += 4
                else_body = self.parse_list(stop_reserved={'fi'}, stop_chars=set())
                break
            else:
                break
        self.skip_spaces()
        if self.peek_reserved() != 'fi':
            self.err(self.pos, "word, escaped_char, unescaped_char, " + WORD_EXPECTED + ", redirect_direction, heredoc, elif_part, else_part, and_or_list_sep, or compound_list_sep")
        self.pos += 2
        return Node('if', cond=cond, then_body=then_body, elifs=elifs, else_body=else_body, start=start)

    def parse_while(self):
        start = self.pos
        self.pos += 5
        cond = self.parse_list(stop_reserved={'do'}, stop_chars=set())
        if self.peek_reserved() != 'do':
            self.err(self.pos, "EOI, normal_newline, command, or compound_list_sep")
        self.pos += 2
        body = self.parse_list(stop_reserved={'done'}, stop_chars=set())
        if self.peek_reserved() != 'done':
            self.err(self.pos, "EOI, and_or_list_sep, or compound_list_sep")
        self.pos += 4
        return Node('while', cond=cond, body=body, start=start)

    def parse_for(self):
        start = self.pos
        self.pos += 3
        self.skip_spaces()
        if self.starts('(('):
            # arith for
            self.pos += 2
            ap = ArithParser(self.s, self.pos)
            try:
                init = ap.parse()
            except Exception:
                self.err(self.pos, "assign")
            self.pos = ap.pos; self.skip_spaces()
            if self.peek_char() != ';':
                self.err(self.pos, "comp_op, assign_op, arith_op, or factor_op")
            self.pos += 1
            ap = ArithParser(self.s, self.pos)
            try: cond = ap.parse()
            except Exception: self.err(self.pos, "assign")
            self.pos = ap.pos; self.skip_spaces()
            if self.peek_char() != ';': self.err(self.pos, "assign")
            self.pos += 1
            ap = ArithParser(self.s, self.pos)
            try: incr = ap.parse()
            except Exception: self.err(self.pos, "assign")
            self.pos = ap.pos; self.skip_spaces()
            if not self.starts('))'):
                self.err(self.pos, "assign")
            self.pos += 2
            # expect ; or newline then do
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] == ';': self.pos += 1
            while self.pos < self.n and self.s[self.pos] == '\n':
                self.pos += 1; self.process_heredocs()
            self.skip_spaces()
            if self.peek_reserved() != 'do':
                self.err(self.pos, "normal_newline")
            self.pos += 2
            body = self.parse_list(stop_reserved={'done'}, stop_chars=set())
            if self.peek_reserved() != 'done': self.err(self.pos, "EOI, and_or_list_sep, or compound_list_sep")
            self.pos += 4
            return Node('arithfor', init=init, cond=cond, incr=incr, body=body, start=start)
        m = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
        if not m:
            self.err(self.pos, "arith_for_exprs")
        var = m.group(0); self.pos += m.end()
        self.skip_spaces()
        words = []
        if self.peek_reserved() == 'in':
            self.pos += 2
            while True:
                self.skip_spaces()
                if self.pos >= self.n or self.s[self.pos] in ';\n':
                    break
                if self.peek_reserved() == 'do':
                    break
                words.append(self.parse_word())
        else:
            self.err(self.pos, "arith_for_exprs")
        # separator
        if self.pos < self.n and self.s[self.pos] == ';': self.pos += 1
        while self.pos < self.n and self.s[self.pos] == '\n':
            self.pos += 1; self.process_heredocs()
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] == ';': self.pos += 1
        self.skip_spaces()
        if self.peek_reserved() != 'do':
            self.err(self.pos, "word or normal_newline")
        self.pos += 2
        body = self.parse_list(stop_reserved={'done'}, stop_chars=set())
        if self.peek_reserved() != 'done':
            self.err(self.pos, "EOI, and_or_list_sep, or compound_list_sep")
        self.pos += 4
        return Node('for', var=var, words=words, body=body, start=start)

    def parse_case(self):
        start = self.pos
        self.pos += 4
        self.skip_spaces()
        subject = self.parse_word()
        self.skip_spaces()
        if self.peek_reserved() != 'in':
            self.err(self.pos, "word or normal_newline")
        self.pos += 2
        items = []
        while True:
            while self.pos < self.n and self.s[self.pos] in ' \t\n':
                if self.s[self.pos] == '\n': self.pos += 1; self.process_heredocs()
                else: self.pos += 1
            if self.pos >= self.n:
                self.err(self.pos, "word or normal_newline")
            if self.peek_reserved() == 'esac':
                self.pos += 4; break
            # patterns
            patterns = []
            while True:
                self.skip_spaces()
                pat = self.parse_word(in_case_pattern=True)
                patterns.append(pat)
                self.skip_spaces()
                if self.pos < self.n and self.s[self.pos] == '|':
                    self.pos += 1; continue
                break
            self.skip_spaces()
            if self.pos >= self.n or self.s[self.pos] != ')':
                self.err(self.pos, "word or normal_newline")
            self.pos += 1
            body = self.parse_list(stop_reserved={'esac'}, stop_chars=set(), stop_ddsemi=True)
            if self.starts(';;'):
                self.pos += 2
            items.append(Node('caseitem', patterns=patterns, body=body))
            # loop
        return Node('case', subject=subject, items=items, start=start)

    def parse_conditional(self):
        start = self.pos
        self.pos += 2
        expr = self.parse_cond_or()
        self.skip_spaces()
        if not self.starts(']]'):
            self.err(self.pos, "escaped_char, unescaped_char, literal_span, any_string_span, any_char_span, command_span, proc_subst_direction, backtick_span, expr_span, param_ex_span, param_span, double_quoted_span, single_quoted_span, or cond_op")
        self.pos += 2
        return Node('conditional', expr=expr, start=start)
    def parse_cond_or(self):
        left = self.parse_cond_and()
        while True:
            self.skip_spaces()
            if self.starts('||'):
                self.pos += 2; right = self.parse_cond_and(); left = Node('cond_bin', op='||', left=left, right=right)
            else: break
        return left
    def parse_cond_and(self):
        left = self.parse_cond_primary()
        while True:
            self.skip_spaces()
            if self.starts('&&'):
                self.pos += 2; right = self.parse_cond_primary(); left = Node('cond_bin', op='&&', left=left, right=right)
            else: break
        return left
    def parse_cond_primary(self):
        self.skip_spaces()
        if self.pos < self.n and self.s[self.pos] == '(':
            raise ShellPanic("src/parser.rs:661:18", "internal error: entered unreachable code")
        left = self.parse_word(in_conditional=True)
        self.skip_spaces()
        # check operator
        op = None
        for cand in ('==','!=','-eq','-ne','-lt','-le','-gt','-ge','='):
            if self.s.startswith(cand, self.pos):
                # ensure boundary for -xx and = etc
                after = self.pos+len(cand)
                if cand.startswith('-'):
                    if after < self.n and (self.s[after].isalnum() or self.s[after]=='_'):
                        continue
                op = cand; break
        if op:
