# ---- Parser extra methods (dollar, quotes, backtick) ----
def _parser_parse_dquote(self):
    # pos at opening "
    self.pos += 1
    spans = []
    while self.pos < self.n:
        c = self.s[self.pos]
        if c == '"':
            self.pos += 1
            return ('dquote', spans)
        if c == '\\':
            if self.pos+1 < self.n and self.s[self.pos+1] in '$`"\\':
                spans.append(('lit', self.s[self.pos+1])); self.pos += 2; continue
            else:
                spans.append(('lit', '\\')); self.pos += 1; continue
        if c == '`':
            spans.append(self.parse_backtick()); continue
        if c == '$':
            spans.append(self.parse_dollar()); continue
        # literal run
        st = self.pos
        while self.pos < self.n and self.s[self.pos] not in '"$`\\':
            self.pos += 1
        spans.append(('lit', self.s[st:self.pos]))
    self.err(self.n, "command_span, backtick_span, expr_span, param_ex_span, param_span, or literal_in_double_quoted_span")

def _parser_parse_backtick(self):
    start = self.pos
    i = self.pos + 1
    while i < self.n:
        if self.s[i] == '\\':
            i += 2; continue
        if self.s[i] == '`':
            break
        i += 1
    if i >= self.n:
        self.err(self.n, "word, escaped_char, unescaped_char, " + WORD_EXPECTED + ", redirect_direction, heredoc, and_or_list_sep, or compound_list_sep")
    content = self.s[self.pos+1:i]
    sub = Parser(content)
    try:
        lst = sub.parse()
    except ParseError as e:
        raise ParseError(e.pos + start + 1, e.expected)
    self.pos = i + 1
    return ('backtick', lst)

def _parser_parse_dollar(self, in_heredoc=False):
    start = self.pos
    # $ at pos
    if self.pos + 1 < self.n and self.s[self.pos+1] == '(':
        # try arithmetic $(( ... ))
        if self.pos + 2 < self.n and self.s[self.pos+2] == '(':
            save = self.pos
            ap = ArithParser(self.s, self.pos+3)
            try:
                expr = ap.parse()
                ap.skip()
                if self.s.startswith('))', ap.pos):
                    self.pos = ap.pos + 2
                    return ('expr', expr)
                raise ValueError("no ))")
            except Exception:
                self.pos = save
        # command substitution
        self.pos += 2
        body = self.parse_list(stop_reserved=set(), stop_chars={')'})
        # allow newlines
        while self.pos < self.n and self.s[self.pos] == '\n':
            self.pos += 1; self.process_heredocs()
            b2 = self.parse_list(stop_reserved=set(), stop_chars={')'})
            body.items.extend(b2.items)
        self.skip_spaces()
        if self.pos >= self.n or self.s[self.pos] != ')':
            self.err(self.pos, "word, escaped_char, unescaped_char, " + WORD_EXPECTED + ", redirect_direction, heredoc, and_or_list_sep, or compound_list_sep")
        self.pos += 1
        return ('cmd', body)
    if self.pos + 1 < self.n and self.s[self.pos+1] == '{':
        return self.parse_paramex()
    # $var
    self.pos += 1
    if self.pos < self.n and self.s[self.pos] in '@*#?$!-_':
        name = self.s[self.pos]; self.pos += 1
        return ('param', name)
    m = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
    if m:
        self.pos += m.end()
        return ('param', m.group(0))
    self.err(self.pos, "var_name")

def _parser_parse_paramex(self):
    # pos at $ , next is {
    self.pos += 2
    length = False
    name = None
    if self.pos < self.n and self.s[self.pos] == '#':
        # lookahead
        if self.pos+1 < self.n and self.s[self.pos+1] == '}':
            self.err(self.pos+1, "var_name")
        if self.pos+1 < self.n and self.s[self.pos+1] == '#' and self.pos+2 < self.n and self.s[self.pos+2] == '}':
            name = '#'; self.pos += 1
        elif self.pos+1 < self.n and self.s[self.pos+1] in '@*':
            length = True
            name = self.s[self.pos+1]; self.pos += 2
            # consume name char already
            info = {'name': name, 'length': length, 'index': None, 'op': None}
            return self._finish_paramex(info)
        else:
            length = True
            self.pos += 1
            # parse var name below
            name = self._parse_var_name_for_paramex()
            info = {'name': name, 'length': length, 'index': None, 'op': None}
            return self._finish_paramex(info)
    else:
        name = self._parse_var_name_for_paramex()
    info = {'name': name, 'length': length, 'index': None, 'op': None}
    return self._finish_paramex(info)

def _parser_parse_var_name_for_paramex(self):
    if self.pos < self.n and self.s[self.pos] in '@*#?$!-_':
        ch = self.s[self.pos]; self.pos += 1; return ch
    m = re.match(r'[A-Za-z0-9_]+', self.s[self.pos:])
    if m:
        self.pos += m.end(); return m.group(0)
    self.err(self.pos, "var_name")

def _parser_finish_paramex(self, info):
    # index ?
    if self.pos < self.n and self.s[self.pos] == '[':
        close = self.s.find(']', self.pos)
        if close == -1:
            self.err(self.pos, "assign")
        raw = self.s[self.pos+1:close]
        # validate as arith (allow empty? no)
        if raw.strip() == '':
            self.err(self.pos+1, "assign")
        ap = ArithParser(raw, 0)
        try:
            expr = ap.parse(); ap.skip()
            if ap.pos != len(raw):
                raise ValueError("trailing")
        except Exception:
            self.err(self.pos+1, "assign")
        info['index'] = expr
        self.pos = close + 1
    if self.pos < self.n and self.s[self.pos] == '}':
        self.pos += 1
        return ('paramex', info)
    # operators
    if self.starts(':-') or self.starts(':='):
        opname = self.s[self.pos:self.pos+2]; self.pos += 2
        word = self._parse_word_until_brace()
        info['op'] = ('default' if opname.endswith('-') else 'assign_default', word)
        if self.pos < self.n and self.s[self.pos] == '}':
            self.pos += 1; return ('paramex', info)
        self.err(self.pos, "param_op")
    if self.pos < self.n and self.s[self.pos] in '-=':
        opch = self.s[self.pos]; self.pos += 1
        word = self._parse_word_until_brace()
        info['op'] = ('default' if opch == '-' else 'assign_default', word)
        if self.pos < self.n and self.s[self.pos] == '}':
            self.pos += 1; return ('paramex', info)
        self.err(self.pos, "param_op")
    if self.pos < self.n and self.s[self.pos] == '/':
        global_replace = False
        self.pos += 1
        if self.pos < self.n and self.s[self.pos] == '/':
            global_replace = True; self.pos += 1
        pattern = self._parse_word_until_slash_or_brace()
        replacement = None
        if self.pos < self.n and self.s[self.pos] == '/':
            self.pos += 1
            replacement = self._parse_word_until_brace()
        info['op'] = ('replace', global_replace, pattern, replacement)
        if self.pos < self.n and self.s[self.pos] == '}':
            self.pos += 1; return ('paramex', info)
        self.err(self.pos, "param_op")
    self.err(self.pos, "param_op")

def _parser_parse_word_until_brace(self):
    # parse a word terminated by }
    start = self.pos
    spans = []
    # Use parse_word but it doesn't stop at }; we implement manual loop using parse_word on a substring:
    # Find logic: repeatedly parse spans until }
    # We'll reuse parse_word by temporarily ... instead directly loop similar to parse_word with } stop
    # Simpler: collect spans by calling helper parsing one span at a time is complex.
    # Approach: scan to determine end is tricky due nested. Use parse_word with monkey: parse_word stops at {} (it breaks on { and }).
    # Our parse_word breaks when c in '{}', so it will stop at }.
    w = self.parse_word()
    return w

def _parser_parse_word_until_slash_or_brace(self):
    # parse word stopping at / or }
    # parse_word does not stop at /; we need manual: save pos, parse spans until / or }
    # We can parse char by char leveraging parse_word on substring up to next / at nesting level.
    # Determine scan index
    i = self.pos
    depth_brace = 0
    # crude scan for '/' or '}' not inside quotes/$()
    while i < self.n:
        ch = self.s[i]
        if ch == '\\':
            i += 2; continue
        if ch == '\'':
            j = self.s.find('\'', i+1); i = self.n if j==-1 else j+1; continue
        if ch == '"':
            j = i+1
            while j < self.n and self.s[j] != '"':
                if self.s[j] == '\\': j += 1
                j += 1
            i = j+1; continue
        if ch == '$' and i+1 < self.n and self.s[i+1] == '{':
            depth_brace += 1; i += 2; continue
        if ch == '}' :
            if depth_brace == 0:
                break
            depth_brace -= 1; i += 1; continue
        if ch == '/' and depth_brace == 0:
            break
        i += 1
    end = i
    subtext = self.s[self.pos:end]
    # parse subtext as a word using a temporary parser over it; but spans that are $ etc need parse
    # Use Parser on subtext to parse_word at start
    sub = Parser(subtext)
    w = sub.parse_word()
    self.pos = end
    return w

Parser.parse_dquote = _parser_parse_dquote
Parser.parse_backtick = _parser_parse_backtick
Parser.parse_dollar = _parser_parse_dollar
Parser.parse_paramex = _parser_parse_paramex
Parser._parse_var_name_for_paramex = _parser_parse_var_name_for_paramex
Parser._finish_paramex = _parser_finish_paramex
Parser._parse_word_until_brace = _parser_parse_word_until_brace
Parser._parse_word_until_slash_or_brace = _parser_parse_word_until_slash_or_brace
