# ---------------- Shell state ----------------
def home_dir():
    h = os.environ.get('HOME')
    if h:
        return h
    try:
        import pwd
        return pwd.getpwuid(os.getuid()).pw_dir
    except Exception:
        return '/'

class Field:
    __slots__ = ('text','segs','glob')
    def __init__(self, text='', segs=None, glob=False):
        self.text = text
        self.segs = segs if segs is not None else [(c, False) for c in text]
        self.glob = glob
    def __repr__(self):
        return f"F({self.text!r},glob={self.glob})"

class Var:
    __slots__=('value',)
    def __init__(self, value):
        self.value = value  # str or list

