# ---------------- Expansion ----------------
def split_field_values(value):
    if value == '':
        return ['']
    # split on each single whitespace char, keeping empties
    parts = re.split(r'([ \t\n\r\f\v])', value)
    # re.split with group includes separators; we need split without keeping but keeping empties between consecutive seps
    # Use manual
    out = []
    cur = ''
    # Actually re.split above returns separators too; rebuild manually:
    out = []
    last = 0
    for m in re.finditer(r'[ \t\n\r\f\v]', value):
        out.append(value[last:m.start()])
        last = m.end()
    out.append(value[last:])
    return out

