        fields = builder.finish_word()
        if apply_glob:
            out = []
            for f in fields:
                if f.glob:
                    matches = glob_expand(f.segs)
                    if matches is None:
                        raise NoMatches()
                    for mtxt in matches:
                        out.append(Field(mtxt))
                else:
                    out.append(f)
            return out
