    def expand_word_string(self, word):
        fields = self.expand_word_fields(word, apply_glob=False)
        return ''.join(f.text for f in fields)

    def expand_word_pattern_segs(self, word):
        fields = self.expand_word_fields(word, apply_glob=False)
        segs = []
        for f in fields:
            if f.segs and len(f.segs) == len(f.text):
                segs.extend(f.segs)
            else:
                segs.extend([(c, False) for c in f.text])
        return segs

