            user = span[1]
            if user:
                ewrite(2, "nsh: warning: ~user is not yet supported\n")
            builder.add_text(home_dir())
        elif kind == 'star':
            builder.add_wild('*')
        elif kind == 'qmark':
            builder.add_wild('?')
        elif kind == 'param':
            name = span[1]
            val = self.get_param_checked(name)
            if quoted:
                if name == '@' and isinstance(val, list):
                    builder.add_quoted_at(val)
                elif isinstance(val, list):
                    builder.add_text(' '.join(val))
                else:
                    builder.add_text(val if val is not None else '')
            else:
                values = self.value_to_field_values(val)
                builder.add_break_values(values)
        elif kind == 'paramex':
