        if index is not None:
            raw = sh.get_var_raw(name)
            if name in ('@','*'):
                # positional index ?
                lst = sh.positional
                idx = eval_arith(index, sh)
                val = lst[idx] if 0 <= idx < len(lst) else ''
            elif isinstance(raw, list):
                idx = eval_arith(index, sh)
                val = raw[idx] if 0 <= idx < len(raw) else ''
            else:
                val = ''
            if length:
                return str(len(val))
            return val
        if length:
            if name in ('@','*'):
                return list(sh.positional)
            if name == '#':
                return str(len(sh.positional))
            if name in ('?','$','!','-'):
                v = sh.get_param_scalar(name)
                return str(len(v if isinstance(v,str) else ''))
            # regular
            if not sh.var_exists(name):
                return '0'
            v = sh.get_param_scalar(name)
            if isinstance(v, list):
                v = ' '.join(v)
            return str(len(v))
        if op is None:
            if name in ('@',):
                return list(sh.positional)
            if name == '*':
