                v = sh.get_param_scalar(name)
                return v if v is not None else ''
            return sh.get_param_scalar(name)
        if op[0] in ('default','assign_default'):
            is_assign = (op[0] == 'assign_default')
            word = op[1]
            if sh.var_exists(name):
                return sh.get_param_scalar(name)
