        if op[0] == 'replace':
            _, global_rep, pat_word, repl_word = op
            v = sh.get_param_scalar(name)
            if isinstance(v, list):
                v = ' '.join(v)
            if v is None:
                v = ''
            pat_segs = self.expand_word_pattern_segs(pat_word)
            if repl_word is None:
                repl = ''
            else:
                # Original only seems to apply replacement when it's a single literal span; we implement conventional string expansion
                # but check: if replacement word has any non-literal span, original returns unchanged for $ etc.
                # We detect: if repl word spans are all 'lit' or 'squote'? Actually quoted replacement also returned unchanged.
                # Keep conventional for literal unquoted only, mimic original otherwise:
                if len(repl_word.spans) == 1 and repl_word.spans[0][0] == 'lit':
                    repl = repl_word.spans[0][1]
                elif all(s[0] == 'lit' for s in repl_word.spans):
                    repl = ''.join(s[1] for s in repl_word.spans)
                else:
                    # Follow original observed: non-literal replacement -> no substitution
                    return v
            return pattern_replace(v, pat_segs, repl, global_rep)
        return ''

    def run_command_subst(self, body):
        return run_command_substitution(self.sh, body)

    def run_proc_subst(self, body):
        return run_process_substitution(self.sh, body)

class FieldBuilder:
    def __init__(self, expander):
        self.exp = expander
        self.fields = []
        self.cur_text = ''
        self.cur_segs = []
        self.cur_active = False
        self.cur_glob = False
    def add_text(self, text):
        if text is None:
            text = ''
        self.cur_text += text
        self.cur_segs.extend([(c, False) for c in text])
        self.cur_active = True
    def add_wild(self, ch):
        self.cur_text += ch
        self.cur_segs.append((ch, True))
        self.cur_active = True
        self.cur_glob = True
    def _push_cur(self):
        self.fields.append(Field(self.cur_text, list(self.cur_segs), self.cur_glob))
        self.cur_text = ''; self.cur_segs = []; self.cur_active = False; self.cur_glob = False
    def add_break_values(self, values):
        if self.cur_active:
            self._push_cur()
        for v in values:
            self.fields.append(Field(v))
        self.cur_text=''; self.cur_segs=[]; self.cur_active=False; self.cur_glob=False
    def add_break_text_field(self, f):
        # push current if active, then start new current with f
        if self.cur_active:
            self._push_cur()
        # set cur to f
        self.cur_text = f.text; self.cur_segs = list(f.segs) if f.segs else [(c,False) for c in f.text]
        self.cur_active = True; self.cur_glob = f.glob
    def add_quoted_at(self, args):
        if not args:
            return
        self.cur_text += args[0]
        self.cur_segs.extend([(c,False) for c in args[0]])
        self.cur_active = True
        # push this as a completed field and add rest as completed
        self._push_cur()
        for a in args[1:]:
            self.fields.append(Field(a))
        # cur inactive
    def finish_word(self):
        if self.cur_active:
            self._push_cur()
        # if no fields, return one empty? Caller expects at least... For word like "$@" with no args in unquoted? param handling gave [''] so fields non-empty.
        # For empty word due to "$@" quoted no args, fields may be []
        return self.fields
    def finish_for_dquote(self):
        # returns (completed fields, cur or None)
        fields = list(self.fields)
        cur = None
        if self.cur_active:
            cur = Field(self.cur_text, list(self.cur_segs), self.cur_glob)
        return (fields, cur)

def pattern_replace(value, pat_segs, repl, global_rep):
