def pattern_replace(value, pat_segs, repl, global_rep):
    # Find matches of glob pattern as substring
    # If pattern is empty: original ${x/} deleted first char; ${x//} deleted all.
    pat_text = ''.join(c for c,_ in pat_segs)
    if pat_text == '':
        if global_rep:
            return ''
        else:
            return value[1:] if value else value
    # Build matching: find leftmost match (shortest? glob * greedy). Use regex generated from pattern where * -> .* etc
    rx_parts = []
    for ch, wild in pat_segs:
        if wild and ch == '*':
            rx_parts.append('(.*?)') if not global_rep else rx_parts.append('(.*?)')
        elif wild and ch == '?':
            rx_parts.append('.')
        else:
            rx_parts.append(re.escape(ch))
    # For replacement we need find substring that fully matches pattern. Use regex search with non-greedy for * but allow greedy at end?
    # Simpler: try all substrings starting at each index, choose smallest length that matches (for patterns ending with * it may need longest: handle)
    def find_match(s, start=0):
        # returns (i,j) or None
        for i in range(start, len(s)+1):
            # try lengths: if pattern contains '*', prefer longest? Original ${x/*/Y} on hello gave Y (whole). * alone matches whole.
            # generate candidate lengths in order: if any '*' wild, try longest first else shortest
            has_star = any(w and c=='*' for c,w in pat_segs)
            lengths = range(len(s)-i, -1, -1) if has_star else range(0, len(s)-i+1)
            for L in lengths:
                sub = s[i:i+L]
                if glob_match(pat_segs, sub):
                    return (i, i+L)
        return None
    if not global_rep:
        m = find_match(value, 0)
        if not m:
            return value
        i,j = m
        return value[:i] + repl + value[j:]
    else:
        res = ''
        idx = 0
        # avoid infinite empty match
        while idx <= len(value):
            m = find_match(value, idx)
            if not m:
                res += value[idx:]; break
            i,j = m
            res += value[idx:i] + repl
            if j == i:
                if j < len(value):
                    res += value[j]; idx = j+1
                else:
                    break
            else:
                idx = j
            if idx > len(value):
                break
        return res

# arithmetic eval
def eval_arith(node, shell):
    k = node.kind
    if k == 'a_num':
        raw = node.raw
        try:
            v = int(raw, 10)
        except:
            v = 0
        if v > 2147483647 or v < -2147483648:
            raise ShellPanic("src/parser.rs:492:67", f"called `Result::unwrap()` on an `Err` value: ParseIntError {{ kind: PosOverflow }}")
        return i32(v)
    if k == 'a_var':
        v = shell.get_param_scalar(node.name)
        if isinstance(v, list):
            v = v[0] if v else ''
        if v is None:
            v = ''
        try:
            return i32(int(str(v).strip(), 10))
        except:
            return 0
    if k == 'a_neg':
        return i32(-eval_arith(node.expr, shell))
    if k == 'a_post':
        cur = eval_arith(Node('a_var', name=node.name), shell)
        if node.op == '++':
            new = i32(cur + 1)
        else:
            new = i32(cur - 1)
        shell.set_var(node.name, str(new))
        return new
    if k == 'a_assign':
        v = eval_arith(node.rhs, shell)
        shell.set_var(node.name, str(v))
        return v
    if k == 'a_bin':
        op = node.op
        if op in ('>','<','>=','<=','==','!='):
            l = eval_arith(node.left, shell); r = eval_arith(node.right, shell)
            if op == '>': return 1 if l > r else 0
            if op == '<': return 1 if l < r else 0
            if op == '>=': return 1 if l >= r else 0
            if op == '<=': return 1 if l <= r else 0
            if op == '==': return 1 if l == r else 0
            if op == '!=': return 1 if l != r else 0
        l = eval_arith(node.left, shell); r = eval_arith(node.right, shell)
        if op == '+': return i32(l + r)
        if op == '-': return i32(l - r)
        if op == '*': return i32(l * r)
        if op == '/':
            if r == 0:
                raise ShellPanic("src/eval.rs:38:47", "attempt to divide by zero")
            # Rust i32 division truncates toward zero
            return i32(int(l / r) if (l % r == 0 or (l<0)==(r<0)) else - (abs(l)//abs(r)) if False else (abs(l)//abs(r)) * (1 if (l<0)==(r<0) else -1))
        # unknown
        return 0
    return 0

