def resolve_external(shell, name, env):
    if '/' in name:
        try:
            st = os.stat(name)
        except OSError as e:
            if e.errno == errno.ENOENT or e.errno == errno.ENOTDIR:
                return ('ENOENT', None)
            return ('ENOENT', None)
        if stat_is_dir(name) or not os.access(name, os.X_OK):
            return ('EACCES', None)
        return ('ok', name)
    path = env.get('PATH', '')
    if path == '':
        entries = []
    else:
        entries = path.split(':')
    found_nonexec = False
    for entry in entries:
        cand = (entry if entry != '' else '.') + '/' + name
        try:
            if os.path.isdir(cand):
                if os.path.exists(cand):
                    found_nonexec = True
                continue
            if os.path.isfile(cand) and os.access(cand, os.X_OK):
                return ('ok', cand)
            if os.path.exists(cand):
                found_nonexec = True
        except OSError:
            pass
    if found_nonexec:
        return ('EACCES', None)
    return ('notfound', None)

