def run_process_substitution(shell, body):
    r, w = os.pipe()
    try: os.set_inheritable(r, True)
    except Exception: pass
    pid = os.fork()
    if pid == 0:
        try:
            os.close(r)
            if w != 1:
                os.dup2(w, 1); os.close(w)
            child_reset_signals()
            status = execute_in_subshell_child(shell, body)
            os._exit(status & 0xff if status >=0 else 255)
        except BaseException:
            os._exit(101)
    os.close(w)
    shell.proc_substs.append((r, pid))
    return f"/dev/fd/{r}"

