# ---------------- Execution ----------------
BUILTIN_NAMES = {'alias','bg','cd','echo','eval','exec','exit','export','fg','jobs','pushd','popd','read','set','shift','source','unset','wait'}

def execute_list(shell, lst):
    status = shell.last_status
    if not lst.items:
        return (0, 'normal')
    for item in lst.items:
        if shell.opt_n:
            return (0, 'normal')
        status, flow = execute_andor(shell, item.andor, background=item.background)
        shell.last_status = status
        if flow != 'normal':
            return (status, flow)
    return (status, 'normal')

def execute_andor(shell, andor, background=False):
    src_text = getattr(andor, 'text', '')
    status, flow = execute_pipeline(shell, andor.first, background=background, andor_text=src_text)
    shell.last_status = status
    if shell.opt_e and status != 0:
        raise ExitShell(status)
    if flow != 'normal':
        return (status, flow)
    for op, pipeline in andor.rest:
        if op == '&&' and status != 0:
            continue
        # || buggy: always execute
        status, flow = execute_pipeline(shell, pipeline, background=background, andor_text=src_text)
        shell.last_status = status
        if shell.opt_e and status != 0:
            raise ExitShell(status)
        if flow != 'normal':
            return (status, flow)
    return (status, flow)

def is_simple_literal_name(cmd):
    if cmd.kind != 'simple' or not cmd.words:
        return None
    w = cmd.words[0]
    if len(w.spans) == 1 and w.spans[0][0] == 'lit':
        return w.spans[0][1]
    return None

def should_fork_command(shell, cmd):
    if cmd.kind == 'subshell':
        return True
    if cmd.kind == 'simple':
        name = is_simple_literal_name(cmd)
        if name is None:
            return False
        # alias/function/builtin -> internal
        if name in shell.aliases or name in shell.functions or name in BUILTIN_NAMES or name == 'local':
            return False
        # assignments only?
        if not cmd.words:
            return False
        return True
    return False

def execute_pipeline(shell, pipeline, background=False, andor_text=''):
    cmds = pipeline.commands
    if len(cmds) == 1:
        cmd = cmds[0]
        if background and is_process_pipeline(shell, pipeline):
            return execute_pipeline_background(shell, pipeline, andor_text)
        return execute_command(shell, cmd)
    # multi
    spawned = []  # (pid, is_last)
    prev_read = None
    last_status = 0
    last_flow = 'normal'
    for i, cmd in enumerate(cmds):
        is_last = (i == len(cmds)-1)
        pipe_r = pipe_w = None
        if not is_last:
            pipe_r, pipe_w = os.pipe()
            try: os.set_inheritable(pipe_r, True); os.set_inheritable(pipe_w, True)
            except Exception: pass
        stdin_fd = prev_read
        stdout_fd = pipe_w
        if should_fork_command(shell, cmd):
            pid = spawn_pipeline_command(shell, cmd, stdin_fd, stdout_fd)
            spawned.append((pid, is_last))
            if pipe_w is not None:
                os.close(pipe_w)
            if stdin_fd is not None:
                os.close(stdin_fd)
            prev_read = pipe_r
            if is_last:
                # will wait below
                pass
        else:
            # in-process with temporary fds
            saved = {}
            try:
                if stdin_fd is not None:
                    saved[0] = os.dup(0); os.dup2(stdin_fd, 0)
                if stdout_fd is not None:
                    saved[1] = os.dup(1); os.dup2(stdout_fd, 1)
                status, flow = execute_command(shell, cmd)
            finally:
                if 0 in saved:
                    os.dup2(saved[0], 0); os.close(saved[0])
                if 1 in saved:
                    os.dup2(saved[1], 1); os.close(saved[1])
                if stdin_fd is not None:
                    try: os.close(stdin_fd)
                    except OSError: pass
                if stdout_fd is not None:
                    try: os.close(stdout_fd)
                    except OSError: pass
            prev_read = pipe_r
            if is_last:
                last_status = status; last_flow = flow
            if flow != 'normal':
                # stop pipeline, wait spawned
                if prev_read is not None:
                    try: os.close(prev_read)
                    except OSError: pass
                    prev_read = None
                for pid, _ in spawned:
                    wait_status(pid)
