    # background jobs only if pipeline contains an external simple command (not builtin/function/alias)
    for cmd in pipeline.commands:
        if cmd.kind == 'simple' and cmd.words:
            name = is_simple_literal_name(cmd)
            if name is None:
                continue
            if name in shell.aliases or name in shell.functions or name in BUILTIN_NAMES:
                continue
            return True
        if cmd.kind == 'simple' and not cmd.words:
            continue
        # compound etc not process themselves, but their inner execution may launch their own bg
    return False

