        try:
            child_reset_signals()
            status, flow = (0, 'normal')
            # execute pipeline without background flag
            # avoid infinite recursion: directly call internal pipeline exec
            status, flow = execute_pipeline(shell, pipeline, background=False)
            os._exit(status & 0xff if status >=0 else 255)
        except ExitShell as e:
            os._exit(e.status & 0xff if e.status>=0 else 255)
        except BaseException:
            os._exit(101)
    shell.last_bg_pid = pid
    status = wait_status(pid)
    # print Done to stdout (fd1)
    ewrite(1, f"[1] Done: {andor_text}\n")
    shell.last_status = status
    cleanup_proc_substs(shell)
    return (status, 'normal')

def spawn_pipeline_command(shell, cmd, stdin_fd, stdout_fd):
    pid = os.fork()
    if pid == 0:
        try:
            child_reset_signals()
            if stdin_fd is not None:
                os.dup2(stdin_fd, 0)
            if stdout_fd is not None:
                os.dup2(stdout_fd, 1)
