        st = wait_status(pid)
        shell.last_status = st
        return (st, 'normal')
    if k == 'bracegroup':
        return execute_list(shell, cmd.body)
    if k == 'if':
        return execute_if(shell, cmd)
    if k == 'while':
        return execute_while(shell, cmd)
    if k == 'for':
        return execute_for(shell, cmd)
    if k == 'arithfor':
        return execute_arithfor(shell, cmd)
    if k == 'case':
        return execute_case(shell, cmd)
    if k == 'funcdef':
        shell.functions[cmd.name] = cmd.body
        return (0, 'normal')
    if k == 'conditional':
        v = eval_conditional(shell, cmd.expr)
        st = 0 if v else 1
        shell.last_status = st
        return (st, 'normal')
    if k == 'local':
        return execute_local(shell, cmd)
    if k == 'return':
        return (0, 'return')
    if k == 'break':
        return (0, 'break')
    if k == 'continue':
