        if expr.op == '&&':
            return eval_conditional(shell, expr.left) and eval_conditional(shell, expr.right)
        else:
            return eval_conditional(shell, expr.left) or eval_conditional(shell, expr.right)
    if expr.kind == 'cond_cmp':
        left = exp.expand_word_string(expr.left)
        if expr.op in ('==','=','!='):
            segs = exp.expand_word_pattern_segs(expr.right)
            m = glob_match(segs, left)
            return m if expr.op != '!=' else not m
        else:
            right = exp.expand_word_string(expr.right)
            try: li = int(left.strip())
            except: li = 0
            try: ri = int(right.strip())
            except: ri = 0
            if expr.op == '-eq': return li == ri
            if expr.op == '-ne': return li != ri
            if expr.op == '-lt': return li < ri
            if expr.op == '-le': return li <= ri
            if expr.op == '-gt': return li > ri
            if expr.op == '-ge': return li >= ri
            return False
    return True

