def apply_redirects_or_fail(shell, node):
    if not node.redirects:
        return None
    ap = RedirectApplier(shell, node.redirects)
    if not ap.apply():
        ap.restore(); return False
    return ap

def read_line_from_fd0():
    buf = b''
    got_any = False
    while True:
        try:
            chunk = os.read(0, 1)
        except OSError:
            chunk = b''
        if not chunk:
            if not got_any:
                return None
            break
        got_any = True
        if chunk == b'\n':
            break
        buf += chunk
    # trim end whitespace (Rust trim_end)
    s = buf.decode('utf-8','surrogateescape')
    return s.rstrip()

