    ap = apply_redirects_or_fail(shell, node)
    if ap is False: return (1,'normal')
    try:
        args = argv[1:]
        no_newline = False; escape = False
        if args and args[0] in ('-n','-e','-ne','-en'):
            opt = args[0]
            if 'n' in opt: no_newline = True
            if 'e' in opt: escape = True
            args = args[1:]
        out = ' '.join(args)
        if escape:
            out = out.replace('\\n','\n').replace('\\t','\t')
        if not no_newline:
            out += '\n'
        ewrite(1, out)
        return (0,'normal')
    finally:
        if ap: ap.restore()

def builtin_cd(shell, args):
    old = os.getcwd()
    if not args:
        target = home_dir()
        disp = target
        try:
            os.chdir(target); shell.prev_dir = old; return 0
        except OSError as e:
            ewrite(2, f"nsh: cd: {os.strerror(e.errno)} (os error {e.errno}): `{disp}'\n"); return 1
    a = args[0]
    if a == '':
        return 0
    if a == '-':
        if shell.prev_dir is None:
            return 1
        try:
            os.chdir(shell.prev_dir); return 0
        except OSError as e:
            disp = shell.prev_dir
            ewrite(2, f"nsh: cd: {os.strerror(e.errno)} (os error {e.errno}): `{disp}'\n"); return 1
    target = a
    disp = target if os.path.isabs(target) else os.path.join(old, target)
    try:
        os.chdir(target); shell.prev_dir = old; return 0
    except OSError as e:
        ewrite(2, f"nsh: cd: {os.strerror(e.errno)} (os error {e.errno}): `{disp}'\n"); return 1

def builtin_alias(shell, args):
    if not args:
