    a = args[0]
    m = re.match(r'^([A-Za-z0-9_]+)=(.*)$', a, re.DOTALL)
    if not m:
        ewrite(2, f"nsh: alias:  --> 1:1\n  |\n1 | {a}\n  | ^---\n  |\n  = expected alias\n")
        return 1
    name, body = m.group(1), m.group(2)
    shell.aliases[name] = body
    return 0

def builtin_exec(shell, argv, node):
    args = argv[1:]
    if not args:
        if node.redirects:
            ap = RedirectApplier(shell, node.redirects)
            ap.apply(); ap.restore()
        return (0,'normal')
