            return run_program_mode(shell, content)
        # interactive
        if not os.isatty(1):
            ewrite(2, "nsh: warning: stdout is not a tty\n")
            return 0
        shell.interactive = True
        return interactive_loop(shell)
    except ShellPanic as e:
        print_panic(e)
        return 101
    except ExitShell as e:
        return e.status & 0xff if e.status >=0 else (e.status % 256)
    except UndefinedVar as e:
        ewrite(2, f"nsh: undefined variable `{e.name}'\n")
        return 1
    except KeyboardInterrupt:
        return 130

def run_program_mode(shell, src):
    shell.current_source = src
    try:
        parser = Parser(src)
        lst = parser.parse()
    except ParseError as e:
        ewrite(2, e.render(src))
        return 255
    try:
        status = run_top_list(shell, lst)
        shell.last_status = status
        return status & 0xff if status >=0 else (status % 256)
    except ShellPanic:
        raise
    except ExitShell as e:
        return e.status

def load_rc(shell, home):
    xdg = os.environ.get('XDG_CONFIG_HOME')
    if xdg and os.path.isabs(xdg):
        config_dir = xdg
    else:
        config_dir = os.path.join(home, '.config')
    paths = [os.path.join(home, '.nshrc'), os.path.join(config_dir, 'nsh', 'nshrc')]
    for path in paths:
        if not os.path.isfile(path):
            continue
        try:
            with open(path, 'rb') as f:
                content = f.read().decode('utf-8','surrogateescape')
        except OSError as e:
            raise ShellPanic("src/main.rs:114:34", f"failed to open the file: {rust_os_error(e)}")
        shell.current_source = content
        try:
            parser = Parser(content)
            lst = parser.parse()
        except ParseError as e:
            ewrite(2, e.render(content))
            continue
        try:
            status = run_top_list(shell, lst)
            shell.last_status = status
        except ExitShell as e:
            shell._rc_exit = True
            # stash code in a global-ish attribute
            shell._rc_exit_code = e.status
            # re-raise handling: mark and throw to main? Use ExitShell conversion in caller: we set flag and return code via exception
            raise
    return None

