CLI_HELP_TEMPLATE = """nsh 0.4.2
A command-line shell that focuses on performance and productivity.

USAGE:
    {prog} [FLAGS] [OPTIONS] [FILE]

FLAGS:
    -h, --help       Prints help information
    -l, --login      Behave like a login shell
        --norc       Don't load nshrc
        --version    Print the version

OPTIONS:
    -c <command>        The command to be executed

ARGS:
    <FILE>    The file to be executed
"""

def parse_cli(args, prog):
    # returns (cli_dict, immediate_or_None)
    login_count = 0; norc_count = 0; version_count = 0
    command = None; command_count = 0
    file_arg = None
    used = []  # list of usage tokens for non-positional used args in order
    def add_used(tok):
        if tok not in used: used.append(tok)
    def usage_used_or_default():
        if used:
            return f"{prog} " + ' '.join(used)
        return f"{prog} [FLAGS] [OPTIONS] [FILE]"
    def err_found(tok, suggestion=None):
        if suggestion:
            sug_name, sug_usage = suggestion
            err = (f"error: Found argument '{tok}' which wasn't expected, or isn't valid in this context\n"
                   f"\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{sug_name}\x1b[0m?\n\nUSAGE:\n    {prog} {sug_usage}\n\nFor more information try --help\n")
            return (1, '', err)
        err = (f"error: Found argument '{tok}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {usage_used_or_default()}\n\nFor more information try --help\n")
        return (1, '', err)
    def err_duplicate(display):
        err = (f"error: The argument '{display}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {usage_used_or_default()}\n\nFor more information try --help\n")
        return (1, '', err)
    def suggest(longname):
        candidates = [('version','--version'),('login','--login'),('norc','--norc'),('help','--help')]
        import difflib
        best = None; best_ratio = 0
        for name, usage in candidates:
            r = difflib.SequenceMatcher(None, longname, name).ratio()
            # clap uses strsim jaro winkler threshold ~0.8; approximate
            if r > best_ratio:
                best_ratio = r; best = (name, usage)
        if best and best_ratio > 0.7:
            return best
        return None
    positional_only = False
    i = 0
    help_text = CLI_HELP_TEMPLATE.format(prog=prog)
    while i < len(args):
        tok = args[i]
        if not positional_only and tok == '--':
            positional_only = True; i += 1; continue
        if not positional_only and tok.startswith('--'):
            body = tok[2:]
            name = body.split('=',1)[0]
            if name == 'help':
                return (None, (0, help_text, ''))
            if name in ('login','norc','version'):
                display = f"--{name}"
                if name == 'login':
                    login_count += 1; add_used('--login')
                    if login_count > 1: return (None, err_duplicate('--login'))
                elif name == 'norc':
                    norc_count += 1; add_used('--norc')
                    if norc_count > 1: return (None, err_duplicate('--norc'))
                else:
                    version_count += 1; add_used('--version')
                    if version_count > 1: return (None, err_duplicate('--version'))
                i += 1; continue
            # unknown
            return (None, err_found(tok, suggest(name)))
        if not positional_only and len(tok) > 1 and tok[0] == '-' and tok != '-':
            # short cluster
            j = 1
            consumed_value = False
            while j < len(tok):
                ch = tok[j]
                if ch == 'h':
                    return (None, (0, help_text, ''))
                if ch == 'l':
                    login_count += 1; add_used('--login')
                    if login_count > 1: return (None, err_duplicate('--login'))
                    j += 1; continue
                if ch == 'c':
                    if command_count >= 1:
                        return (None, (1, '', f"error: The argument '-c <command>' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {prog} -c <command>\n\nFor more information try --help\n"))
                    command_count += 1; add_used('-c <command>')
                    rest = tok[j+1:]
                    if rest.startswith('='):
                        rest = rest[1:]
                    if rest != '':
                        command = rest
                    else:
                        # next token
                        if i+1 >= len(args):
                            return (None, (1, '', f"error: The argument '-c <command>' requires a value but none was supplied\n\nUSAGE:\n    {prog} -c <command>\n\nFor more information try --help\n"))
                        nxt = args[i+1]
                        if nxt == '--':
                            return (None, (1, '', f"error: The argument '-c <command>' requires a value but none was supplied\n\nUSAGE:\n    {prog} -c <command>\n\nFor more information try --help\n"))
                        if nxt in ('--help', '-h'):
                            return (None, (0, help_text, ''))
                        command = nxt; i += 1
                    consumed_value = True
                    break
                # unknown short
                return (None, err_found(f"-{ch}"))
            i += 1; continue
        # positional
        if file_arg is not None:
            return (None, err_found(tok))
        file_arg = tok; i += 1
    if version_count == 1:
        # version takes precedence over execution but after duplicate checks
        return (None, (0, "0.4.2\n", ''))
    cli = {'login': login_count>0, 'norc': norc_count>0, 'command': command, 'file': file_arg}
    return (cli, None)

