# ---------------- Interactive ----------------
def repo_status_str(cwd):
    # find git repo
    cur = cwd
    root = None
    while True:
        if os.path.exists(os.path.join(cur, '.git')):
            root = cur; break
        parent = os.path.dirname(cur)
        if parent == cur: break
        cur = parent
    if root is None:
        return ''
    branch = ''
    try:
        import subprocess as _sp
        out = _sp.run(['git','-C',root,'rev-parse','--abbrev-ref','HEAD'], capture_output=True, text=True, timeout=2)
        branch = out.stdout.strip()
        dirty = _sp.run(['git','-C',root,'status','--porcelain'], capture_output=True, text=True, timeout=2)
        # Original repo_status format unknown; use branch plus * if dirty (probed later)
        if dirty.stdout.strip():
            branch = branch + '*'
    except Exception:
        pass
    return branch

def render_prompt_template(shell, tmpl):
    out = ''
    i = 0
    while i < len(tmpl):
        if tmpl.startswith('\\if{', i):
            # parse 3 groups
            j = i + 4
            groups = []
            ok = True
            for g in range(3):
                if j >= len(tmpl) or tmpl[j] != '{' if False else False:
                    pass
                # j points after \if or after previous }; expect '{'
                # Actually after \if, the first { is at part of \if{ : we already consumed it as delimiter, content starts at j
                # Need parse content until matching } skipping \{...}
                depth_content_start = j
                k = j
                buf = ''
                closed = False
                while k < len(tmpl):
                    if tmpl.startswith('\\{', k):
                        end = tmpl.find('}', k)
                        if end == -1:
                            ok = False; break
                        buf += tmpl[k:end+1]; k = end+1; continue
                    if tmpl[k] == '}':
                        closed = True; break
                    buf += tmpl[k]; k += 1
                if not closed:
                    ok = False; break
                groups.append(buf)
                j = k + 1
                if g < 2:
                    if j < len(tmpl) and tmpl[j] == '{':
                        j += 1
                    else:
                        ok = False; break
            if not ok or len(groups) != 3:
                out += tmpl[i]; i += 1; continue
            cond, then_t, else_t = groups
            truth = False
            if cond == 'in_repo':
                truth = repo_status_str(os.getcwd()) != '' or is_in_repo(os.getcwd())
            elif cond == 'in_remote':
                truth = ('SSH_CONNECTION' in os.environ) or ('SSH_TTY' in os.environ)
            out += render_prompt_template(shell, then_t if truth else else_t)
            i = j
            continue
        if tmpl.startswith('\\{', i):
            end = tmpl.find('}', i)
            if end == -1:
                out += tmpl[i]; i += 1; continue
            name = tmpl[i+2:end]
            out += prompt_placeholder(shell, name)
            i = end + 1; continue
        if tmpl.startswith('\\n', i):
            out += '\n'; i += 2; continue
        out += tmpl[i]; i += 1
    return out

def is_in_repo(cwd):
    cur = cwd
    while True:
        if os.path.exists(os.path.join(cur, '.git')):
            return True
        parent = os.path.dirname(cur)
        if parent == cur: return False
        cur = parent

def prompt_placeholder(shell, name):
    colors = {'reset':'\x1b[0m','bold':'\x1b[1m','underline':'\x1b[4m','red':'\x1b[31m','green':'\x1b[32m','yellow':'\x1b[33m','blue':'\x1b[34m','magenta':'\x1b[35m','cyan':'\x1b[36m'}
    if name in colors:
        return colors[name]
    if name == 'username':
        try:
            import pwd; return pwd.getpwuid(os.getuid()).pw_name
        except Exception:
            return os.environ.get('USER','')
    if name == 'hostname':
        try:
            import socket; return socket.gethostname()
        except Exception:
            return ''
    if name == 'current_dir':
        return os.getcwd()
    if name == 'repo_status':
        return repo_status_str(os.getcwd())
    return '{' + name + '}'

def get_prompt(shell):
    tmpl = shell.get_var_raw('PROMPT')
    if not isinstance(tmpl, str) or tmpl == '':
        # if PROMPT var exists as empty, original may use empty? We'll use default if not set.
        if shell.get_var_raw('PROMPT') is None:
            tmpl = r"\{cyan}\{bold}\{current_dir} $\{" + "reset} "
            tmpl = "\\{cyan}\\{bold}\\{current_dir} $\\{reset} "
        else:
            tmpl = tmpl if isinstance(tmpl,str) else ''
    return render_prompt_template(shell, tmpl)

def prompt_visible_len(rendered):
    # strip ANSI escapes
    txt = re.sub(r'\x1b\[[0-9;]*m', '', rendered)
    return len(txt)

def highlight_input(shell, text):
    # approximate highlighting: first word green/red, quoted strings cyan
    if not text:
        return "\x1b[38;5;9m\x1b[0m"
    # tokenize keeping spaces
    # Find first word end
    out = ''
    i = 0
    # simplistic: process segments: quotes vs non-quotes, first token color based on validity
    # determine first token
    m = re.match(r'\S+', text)
    valid = False
    if m:
        first = m.group(0)
        base = first.rstrip('=')
        if first in shell.functions or first in BUILTIN_NAMES or first in shell.aliases:
            valid = True
        elif '=' in first and re.match(r'^[A-Za-z0-9_]+= ', first) is None and re.match(r'^[A-Za-z0-9_]+=', first):
            valid = False
        else:
            # check executable in PATH
            env = shell.build_env(None)
            kind, _ = resolve_external(shell, first, env)
            valid = (kind == 'ok')
            if first in ('if','then','else','elif','fi','for','while','do','done','case','esac','function','local','return','break','continue','{','}','[[',']]','(',')'):
                valid = True
    first_done = False
    in_first = True
    # Build char by char with quote coloring
    pos = 0
    # Use regex tokens: quoted strings or other chars
    while pos < len(text):
        if text[pos] in '\'"':
            q = text[pos]; end = text.find(q, pos+1)
            if end == -1:
                seg = text[pos:]; pos = len(text)
            else:
                seg = text[pos:end+1]; pos = end+1
            out += f"\x1b[38;5;14m{seg}\x1b[0m"
            # quoted segment may be after first, but if first token is quote, first is done
            in_first = False
            continue
        # non-quoted chunk until quote or space?
        start = pos
        while pos < len(text) and text[pos] not in '\'"':
            pos += 1
        seg = text[start:pos]
        if in_first:
            # seg starts with first token
            if m:
                tok = m.group(0)
                # assignment coloring: name= red, rest?
                if re.match(r'^[A-Za-z0-9_]+=', tok):
                    eq = tok.find('=')+1
                    out += f"\x1b[38;5;9m{tok[:eq]}\x1b[0m"
                    rest = seg[len(tok):]
                    # value part after = may continue; treat rest of seg as plain for now
                    # But seg may include token exactly; append rest plain
                    if len(tok) < len(seg):
                        out += seg[len(tok):]
                    # Actually seg may be longer than token if token followed by ??? no spaces in seg, token is whole seg if not quote
                else:
                    col = 10 if valid else 9
                    out += f"\x1b[38;5;{col}m{tok}\x1b[0m" + seg[len(tok):]
            else:
                out += seg
            in_first = False
        else:
            out += seg
    return out

def interactive_loop(shell):
    import termios
    fd_in = 0
    is_tty_in = False
    old_attrs = None
    try:
        old_attrs = termios.tcgetattr(fd_in)
        is_tty_in = True
    except Exception:
        is_tty_in = False
    def set_raw():
        if not is_tty_in: return
        try:
            attrs = termios.tcgetattr(fd_in)
            # raw like: disable ICANON ECHO etc
            import copy
            new = copy.deepcopy(attrs)
            new[0] = attrs[0] & ~(termios.BRKINT | termios.ICRNL | termios.INPCK | termios.ISTRIP | termios.IXON)
            new[1] = attrs[1] & ~(termios.OPOST)
            new[2] = new[2] | termios.CS8
            new[3] = attrs[3] & ~(termios.ECHO | termios.ICANON | termios.IEXTEN | termios.ISIG)
            new[6][termios.VMIN] = 1
            new[6][termios.VTIME] = 0
            termios.tcsetattr(fd_in, termios.TCSANOW, new)
        except Exception: pass
    def set_cooked():
        if old_attrs is not None:
            try: termios.tcsetattr(fd_in, termios.TCSANOW, old_attrs)
            except Exception: pass
    try:
        while True:
            prompt = get_prompt(shell)
            plen = prompt_visible_len(prompt)
            # initial filler line like original
            try:
                cols = os.get_terminal_size(1).columns
            except Exception:
                cols = 80
            ewrite(1, "\x1b[1m\x1b[7m$\x1b[0m" + " "*(max(0,cols-1)) + "\r" + prompt)
            line, action = read_editor_line(shell, prompt, plen, set_raw, set_cooked)
            if action == 'eof':
                break
            if action == 'ctrlc':
                continue
            # execute
            set_cooked()
            ewrite(1, "\n")
            if line.strip() == '':
                continue
            # history record
            try:
                now = int(time.time())
                cwd = os.getcwd()
                with open(shell.history_path, 'a', encoding='utf-8') as hf:
                    hf.write(f"{now}\t{cwd}\t{line}\n")
                shell.history.append((str(now), cwd, line))
            except Exception:
                pass
            try:
                status = run_program_mode(shell, line)
                shell.last_status = status
                if getattr(shell, '_exit_requested', False):
                    break
            except ExitShell as e:
                return e.status & 0xff if e.status>=0 else e.status % 256
            except ShellPanic as e:
                print_panic(e); return 101
            except UndefinedVar as e:
                ewrite(2, f"nsh: undefined variable `{e.name}'\n"); shell.last_status = 1
    finally:
        set_cooked()
    return shell.last_status & 0xff if shell.last_status>=0 else shell.last_status % 256

def read_editor_line(shell, prompt, plen, set_raw, set_cooked):
    # returns (line, action) action: ok/eof/ctrlc
    set_raw()
    buf = []
    cursor = 0
    hist = [cmd for _,_,cmd in shell.history]
    hist_index = None
    saved = ''
    # completion state etc.
    def render():
        text = ''.join(buf)
        cols = plen + len(text)
        ewrite(1, "\x1b[?25l" + "\r" + f"\x1b[{plen}C" + "\x1b[K" + highlight_input(shell, text) + "\r" + f"\x1b[{plen+cursor}C" + "\x1b[?25h")
    render_initial = False
    # initial empty render like original: it renders empty red segment on first keypress only; but show nothing initially beyond prompt
    while True:
        try:
            data = os.read(0, 1)
        except OSError:
            return ('', 'eof')
        if not data:
            if not buf:
                return ('', 'eof')
            else:
                continue
        b = data[0]
        if b == 0x1b:
            # escape sequence: read more with select
            seq = b''
            import select
            # peek
            while True:
                r,_,_ = select.select([0],[],[],0.01)
                if not r: break
                chunk = os.read(0,1)
                if not chunk: break
                seq += chunk
                if len(seq) >= 2 and seq[0:1] == b'[' and chr(seq[-1]) in 'ABCDHF~':
                    break
                if len(seq) == 1 and seq.decode(errors='ignore').isalpha():
                    break
                if len(seq) > 6: break
            s = seq.decode('utf-8','ignore')
            if s == '[A': # up
                if hist:
                    if hist_index is None:
                        saved = ''.join(buf); hist_index = len(hist)-1
                    elif hist_index > 0:
                        hist_index -= 1
                    buf = list(hist[hist_index]); cursor = len(buf); render()
                continue
            if s == '[B': # down
                if hist_index is not None:
                    if hist_index < len(hist)-1:
                        hist_index += 1; buf = list(hist[hist_index])
                    else:
                        hist_index = None; buf = list(saved)
                    cursor = len(buf); render()
                continue
            if s == '[C': cursor = min(len(buf), cursor+1); render(); continue
            if s == '[D': cursor = max(0, cursor-1); render(); continue
            if s == '[H' or s == '[1~' or s == '[OH': cursor = 0; render(); continue
            if s == '[F' or s == '[4~' or s == '[OF': cursor = len(buf); render(); continue
            if s == '[3~': # delete
                if cursor < len(buf): del buf[cursor]; render()
                continue
            if s == 'f' or s == '[1;5C': # alt-f / ctrl-right: next word
                # move to next word end
                txt=''.join(buf); i=cursor
                while i < len(txt) and txt[i]==' ': i+=1
                while i < len(txt) and txt[i]!=' ': i+=1
                cursor=i; render(); continue
            if s == 'b' or s == '[1;5D':
                txt=''.join(buf); i=cursor
                while i>0 and txt[i-1]==' ': i-=1
                while i>0 and txt[i-1]!=' ': i-=1
                cursor=i; render(); continue
            # unknown escape
            continue
        if b in (0x0d, 0x0a):
            set_cooked()
            return (''.join(buf), 'ok')
        if b == 0x03: # Ctrl-C clear input
            # original clears input and shows fresh prompt; emulate by returning ctrlc with newline handling in caller?
            ewrite(1, "^C\n")
            set_cooked()
            return ('', 'ctrlc')
        if b == 0x04: # Ctrl-D
            if not buf:
                set_cooked(); return ('','eof')
            if cursor < len(buf):
                del buf[cursor]; render()
            continue
        if b == 0x0c: # Ctrl-L
            ewrite(1, "\x1b[H\x1b[2J" + prompt)
            # re-render input
            render(); continue
        if b == 0x01: cursor=0; render(); continue
        if b == 0x05: cursor=len(buf); render(); continue
        if b == 0x0b: # Ctrl-K
            del buf[cursor:]; render(); continue
        if b == 0x15: # Ctrl-U (not documented but common)
            del buf[:]; cursor=0; render(); continue
        if b == 0x17: # Ctrl-W delete previous word
            txt=''.join(buf); i=cursor
            while i>0 and txt[i-1]==' ': i-=1
            while i>0 and txt[i-1]!=' ': i-=1
            del buf[i:cursor]; cursor=i; render(); continue
        if b in (0x7f, 0x08):
            if cursor>0:
                del buf[cursor-1]; cursor-=1; render()
            continue
