            text=''.join(buf)
            new_text, new_cursor = do_completion(shell, text, cursor)
            if new_text is not None:
                buf=list(new_text); cursor=new_cursor; render()
            continue
        if b < 0x20:
            continue
        # printable: decode utf8 continuation
        bytes_buf = bytes([b])
        if b >= 0xf0: need=3
        elif b >= 0xe0: need=2
        elif b >= 0xc0: need=1
        else: need=0
        for _ in range(need):
            try:
                cb = os.read(0,1)
                bytes_buf += cb
            except Exception: break
        try:
            ch = bytes_buf.decode('utf-8')
        except Exception:
            ch = bytes_buf.decode('utf-8','ignore')
        for ch_c in ch:
            buf.insert(cursor, ch_c); cursor+=1
        render()

def do_completion(shell, text, cursor):
    # basic completion
    before = text[:cursor]
    # last token
    m = re.search(r'(\S*)$', before)
    token = m.group(1) if m else ''
