def _read_escape_seq():
    import select
    seq = b''
    while True:
        r,_,_ = select.select([0],[],[],0.01)
        if not r: break
        chunk = os.read(0,1)
        if not chunk: break
        seq += chunk
        if len(seq) >= 2 and seq[0:1] == b'[' and chr(seq[-1]) in 'ABCDHF~':
            break
        if len(seq) == 1 and seq.decode(errors='ignore').isalpha():
            break
        if len(seq) > 6: break
    return seq.decode('utf-8','ignore')

def history_search_mode(shell, cwd_only=False):
    # returns (action, text) action: execute/edit/cancel ; assumes raw mode, uses alt screen
    entries_all = list(reversed(shell.history))
    curcwd = os.getcwd()
    pool = []
    for ts, cwd, cmd in entries_all:
        if cwd_only and cwd != curcwd:
            continue
        pool.append(cmd)
    query = ''
    index = 0
    def filtered():
        if query == '':
            return pool
        return [c for c in pool if query in c]
    label = "history (cwd)> " if cwd_only else "history> "
    rows = 24
    try: rows = os.get_terminal_size(1).lines
    except Exception: pass
    def render():
        flt = filtered()
        sel = flt[index] if flt and index < len(flt) else ''
        out = "\x1b[H\x1b[2J" + label + query + "\r\n" + sel
        out += f"\x1b[{rows};1H" + " Enter: Execute, Tab: Edit, ^C: Quit"
        out += f"\x1b[1;{len(label)+len(query)+1}H"
        ewrite(1, out)
        return sel
    ewrite(1, "\x1b[?1049h")
    try:
        render()
        while True:
            try:
                data = os.read(0,1)
            except OSError:
                return ('cancel','')
            if not data:
                return ('cancel','')
            b = data[0]
            if b == 0x1b:
                s = _read_escape_seq()
                flt = filtered()
                if s == '[A':
                    if index > 0: index -= 1
                    render(); continue
                if s == '[B':
                    if index < len(flt)-1: index += 1
                    render(); continue
                # escape alone / unknown: cancel
                if s == '':
                    return ('cancel','')
                continue
            if b in (0x0d,0x0a):
                sel = render()
                return ('execute', sel)
            if b == 0x09:
                sel = render()
                return ('edit', sel)
            if b == 0x03:
                return ('cancel','')
            if b in (0x7f,0x08):
                if query: query = query[:-1]; index = 0
                render(); continue
            if b < 0x20:
                continue
            # printable utf8
            bb = bytes([b]); need = 3 if b>=0xf0 else 2 if b>=0xe0 else 1 if b>=0xc0 else 0
            for _ in range(need):
                try: bb += os.read(0,1)
                except Exception: break
            try: ch = bb.decode('utf-8')
            except Exception: ch = bb.decode('utf-8','ignore')
            query += ch; index = 0; render()
    finally:
        ewrite(1, "\x1b[?1049l")

